local function __VOIDCXZ_RUN(name, source)
    local fn, err = loadstring(source, name)
    if not fn then
        error("VoidcxzHub failed to compile " .. tostring(name) .. ": " .. tostring(err), 0)
    end
    local ok, result = pcall(fn)
    if not ok then
        error("VoidcxzHub failed while loading " .. tostring(name) .. ": " .. tostring(result), 0)
