__VOIDCXZ_SOURCE[[[Features/AntiGuard.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Anti Guard
-- ✅ Check DropHeldEgg.Enabled
-- ✅ True → Lock Camera → CFrame Safe Zone → Wait 1s → Return → Unlock Camera
-- ✅ False → Reset
-- ✅ Loop ដដែល
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ProximityPromptService = game:GetService("ProximityPromptService")
local Workspace = game:GetService("Workspace")

local Player = Players.LocalPlayer

-- ==================================================
-- SETTINGS
-- ==================================================
local SAFE_ZONE = Vector3.new(550, 70, -431)
local CHECK_INTERVAL = 0.01
local WAIT_AT_SAFE = 1

-- ==================================================
-- STATE
-- ==================================================
local AntiGuardEnabled = false
local CheckThread = nil
local FastClickConnection = nil
local FastClickHeartbeat = nil
local FastClickCounter = 0
local LastState = false
local OriginalCFrame = nil

-- ✅ Camera Lock State
local CameraLockConnection = nil
local LockedCameraCFrame = nil

-- ==================================================
-- GET HUMANOID
-- ==================================================
local function GetHumanoid()
    local Char = Player.Character
    if not Char then return nil, nil end
    return Char:FindFirstChildOfClass("Humanoid"), Char:FindFirstChild("HumanoidRootPart")
end

-- ==================================================
-- GET DROP HELD EGG
-- ==================================================
local function GetDropHeldEgg()
    local PG = Player:FindFirstChild("PlayerGui")
    if not PG then return nil end
    return PG:FindFirstChild("DropHeldEgg", true)
end

-- ==================================================
-- CAMERA LOCK
-- ==================================================
local function LockCamera()
    local Camera = Workspace.CurrentCamera
    if not Camera then return end

    -- ✅ Save Camera CFrame
    LockedCameraCFrame = Camera.CFrame

    -- ✅ Lock Camera រាល់ Frame
    if CameraLockConnection then CameraLockConnection:Disconnect() end
    CameraLockConnection = RunService.RenderStepped:Connect(function()
        if not LockedCameraCFrame then return end
        local Cam = Workspace.CurrentCamera
        if Cam then
            Cam.CFrame = LockedCameraCFrame
            Cam.Focus = LockedCameraCFrame
        end
    end)

    print("[AntiGuard] 🔒 Camera Locked:", LockedCameraCFrame.Position)
end

local function UnlockCamera()
    if CameraLockConnection then
        CameraLockConnection:Disconnect()
        CameraLockConnection = nil
    end
    LockedCameraCFrame = nil
    print("[AntiGuard] 🔓 Camera Unlocked")
end

-- ==================================================
-- CLICK FAST
-- ==================================================
local function ApplyHoldDuration(prompt)
    if not prompt then return end
    pcall(function() prompt.HoldDuration = 0 end)
end

local function ScanAllPrompts()
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("ProximityPrompt") then ApplyHoldDuration(d) end
    end
    local PG = Player:FindFirstChild("PlayerGui")
    if PG then
        for _, d in ipairs(PG:GetDescendants()) do
            if d:IsA("ProximityPrompt") then ApplyHoldDuration(d) end
        end
    end
end

local function StartFastClick()
    ScanAllPrompts()
    if FastClickConnection then FastClickConnection:Disconnect() end
    FastClickConnection = ProximityPromptService.PromptShown:Connect(function(prompt)
        if not AntiGuardEnabled then return end
        ApplyHoldDuration(prompt)
    end)
    if FastClickHeartbeat then FastClickHeartbeat:Disconnect() end
    FastClickCounter = 0
    FastClickHeartbeat = RunService.Heartbeat:Connect(function()
        if not AntiGuardEnabled then return end
        FastClickCounter = FastClickCounter + 1
        if FastClickCounter >= 30 then
            FastClickCounter = 0
            ScanAllPrompts()
        end
    end)
    print("[AntiGuard] Fast Click: ON")
end

local function StopFastClick()
    if FastClickConnection then FastClickConnection:Disconnect() FastClickConnection = nil end
    if FastClickHeartbeat then FastClickHeartbeat:Disconnect() FastClickHeartbeat = nil end
    print("[AntiGuard] Fast Click: OFF")
end

-- ==================================================
-- CFrame + Return (Anti Guard Protection + Camera Lock)
-- ==================================================
local function CFrameAndReturn()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root then
        print("[AntiGuard] ⚠️ Humanoid or Root not found!")
        return
    end

    OriginalCFrame = Root.CFrame
    print("[AntiGuard] 📍 Original Position:", OriginalCFrame.Position)

    -- ✅ Lock Camera
    LockCamera()

    -- ✅ CFrame ទៅ Safe Zone
    pcall(function()
        Root.CFrame = CFrame.new(SAFE_ZONE)
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero
    end)
    print("[AntiGuard] ✅ CFrame → Safe Zone:", SAFE_ZONE)

    -- ✅ Wait 1s
    task.wait(WAIT_AT_SAFE)

    -- ✅ Return មក Position ដើម
    if OriginalCFrame then
        pcall(function()
            Root.CFrame = OriginalCFrame
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
        print("[AntiGuard] ✅ Return → Original Position")
    end

    -- ✅ Unlock Camera
    UnlockCamera()
end

-- ==================================================
-- CHECK LOOP (True/False Loop)
-- ==================================================
local function CheckLoop()
    print("[AntiGuard] CheckLoop Started")
    local DropHeldEgg = nil

    while AntiGuardEnabled do
        task.wait(CHECK_INTERVAL)
        if not AntiGuardEnabled then break end

        if not DropHeldEgg or not DropHeldEgg.Parent then
            DropHeldEgg = GetDropHeldEgg()
        end

        if DropHeldEgg then
            local CurrentState = DropHeldEgg.Enabled == true

            -- ✅ True → CFrame Safe Zone + Camera Lock
            if CurrentState and not LastState then
                print("[AntiGuard] ✅ Egg Collect = TRUE → CFrame Safe Zone")
                LastState = true
                CFrameAndReturn()
            end

            -- ✅ False → Reset
            if not CurrentState and LastState then
                print("[AntiGuard] ❌ Egg Collect = FALSE → Reset")
                LastState = false
            end
        end
    end

    print("[AntiGuard] CheckLoop Stopped")
end

-- ==================================================
-- ENABLE
-- ==================================================
local function EnableAntiGuard()
    if AntiGuardEnabled then return end
    AntiGuardEnabled = true
    LastState = false

    StartFastClick()

    if CheckThread then
        pcall(function() task.cancel(CheckThread) end)
        CheckThread = nil
    end
    CheckThread = task.spawn(CheckLoop)

    print("[AntiGuard] ON")
end

-- ==================================================
-- DISABLE
-- ==================================================
local function DisableAntiGuard()
    if not AntiGuardEnabled then return end
    AntiGuardEnabled = false
    LastState = false

    if CheckThread then
        pcall(function() task.cancel(CheckThread) end)
        CheckThread = nil
    end

    StopFastClick()
    UnlockCamera()

    print("[AntiGuard] OFF")
end

-- ==================================================
-- TOGGLE
-- ==================================================
local function ToggleAntiGuard()
    if AntiGuardEnabled then DisableAntiGuard() else EnableAntiGuard() end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_AntiGuard = {
    Enable = EnableAntiGuard,
    Disable = DisableAntiGuard,
    Toggle = ToggleAntiGuard,
    IsEnabled = function() return AntiGuardEnabled end,
    SAFE_ZONE = SAFE_ZONE,
    WAIT_AT_SAFE = WAIT_AT_SAFE,
    LockCamera = LockCamera,
    UnlockCamera = UnlockCamera,
}

-- ==================================================
-- REGISTER WITH CHARACTER SYSTEM
-- ==================================================
if _G.VOIDCXZ_CharacterSystem then
    _G.VOIDCXZ_CharacterSystem:RegisterFeature({
        Name = "AntiGuard",
        Enable = EnableAntiGuard,
        Disable = DisableAntiGuard,
        IsEnabled = function() return AntiGuardEnabled end,
        OnCharacterAdded = function(Char, Hum, Root)
            if AntiGuardEnabled then
                task.wait(1)
                EnableAntiGuard()
            end
        end
    })
end

print("✅ AntiGuard Feature Loaded (With Camera Lock)")
print("   Safe Zone:", SAFE_ZONE)
print("   Wait:", WAIT_AT_SAFE .. "s")
print("   Camera: Lock → CFrame → Return → Unlock")
]]
__VOIDCXZ_SOURCE[[[Features/AntiTrap.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Anti Trap
-- ✅ Remove ONLY "PlayerTrap" Prefix in workspace.Transient
-- ✅ Loop រាល់ 0.5s
-- ==================================================

local AntiTrapEnabled = false
local RemoveThread = nil

-- ==================================================
-- PREFIX FILTER
-- ==================================================
local TRAP_PREFIX = "PlayerTrap"

-- ==================================================
-- REMOVE ONLY TRAP CHILDREN
-- ==================================================
local function RemoveTrapChildren()
    local Transient = workspace:FindFirstChild("Transient")
    if not Transient then return 0 end

    local Count = 0
    for _, child in ipairs(Transient:GetChildren()) do
        if child.Name:sub(1, #TRAP_PREFIX) == TRAP_PREFIX then
            pcall(function()
                child:Destroy()
                Count = Count + 1
            end)
        end
    end

    return Count
end

-- ==================================================
-- ENABLE
-- ==================================================
local function EnableAntiTrap()
    if AntiTrapEnabled then return end
    AntiTrapEnabled = true

    -- ✅ លុបភ្លាមម្តង
    RemoveTrapChildren()

    -- ✅ Loop រាល់ 0.5s
    if RemoveThread then
        pcall(function() task.cancel(RemoveThread) end)
        RemoveThread = nil
    end

    RemoveThread = task.spawn(function()
        while AntiTrapEnabled do
            task.wait(0.5)
            if AntiTrapEnabled then
                local T = RemoveTrapChildren()
                if T > 0 then
                    print("[AntiTrap] Removed", T, "PlayerTrap(s)")
                end
            end
        end
    end)

    print("[AntiTrap] ON")
end

-- ==================================================
-- DISABLE
-- ==================================================
local function DisableAntiTrap()
    if not AntiTrapEnabled then return end
    AntiTrapEnabled = false

    if RemoveThread then
        pcall(function() task.cancel(RemoveThread) end)
        RemoveThread = nil
    end

    print("[AntiTrap] OFF")
end

-- ==================================================
-- TOGGLE
-- ==================================================
local function ToggleAntiTrap()
    if AntiTrapEnabled then
        DisableAntiTrap()
    else
        EnableAntiTrap()
    end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_AntiTrap = {
    Toggle = ToggleAntiTrap,
    Enable = EnableAntiTrap,
    Disable = DisableAntiTrap,
    IsEnabled = function() return AntiTrapEnabled end,
    RemoveTrapChildren = RemoveTrapChildren,
    TRAP_PREFIX = TRAP_PREFIX,
}

print("✅ AntiTrap Feature Loaded (PlayerTrap Only)")
]]
__VOIDCXZ_SOURCE[[[Features/AttackDrone.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Attack Drone
-- Attack ONLY Top1 | Top2 | Top3
-- ✅ Logic ចាស់ទាំងស្រុង — InitialFlyAndStartLoop (Signed X)
-- ✅ Fly TP មិន Lock + Stop ភ្លាម + Reset CFrame
-- ✅ Lock CFrame តែពេល Follow Mob
-- ✅ Register ជាមួយ CharacterSystem
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Player = Players.LocalPlayer

-- ==================================================
-- SETTINGS
-- ==================================================
local ATTACK_RANGE = 16
local ATTACK_INTERVAL = 0.05
local FOLLOW_SPEED = 500
local FOLLOW_BEHIND_DISTANCE = 3
local SHORT_TP_DISTANCE = 20
local SPAWN_POSITION_1 = Vector3.new(2140, 77, -367)
local SPAWN_POSITION_2 = Vector3.new(5723, 77, -376)
local SAFE_ZONE = Vector3.new(533, 70, -366)
local POINT_1 = Vector3.new(559, 70, -370)
local SAFE_WAIT_TIME = 1
local SPAWN_WAIT_TIME = 2
local ARRIVE_TIMEOUT = 15
local CONTAINER_NAME = "ScrambleLocalVisuals"
local SEARCH_PREFIXES = { "DroneVisual_", "PersonalDrone_" }

local TIER_PRIORITY = {
    ["AugmentedDrone"] = 1,
    ["ReactorDrone"] = 2,
    ["ScrapDrone"] = 3,
}
local MAX_ALLOWED_PRIORITY = 3

-- ==================================================
-- STATE
-- ==================================================
local AttackDroneEnabled = false
local AttackConnection = nil
local FollowConnection = nil
local LockConnection = nil
local BodyVelocity = nil
local BodyGyro = nil
local CurrentTarget = nil
local CurrentTargetPriority = nil
local LastFire = 0
local TraceSequence = 0
local IsLocked = false
local LockCFrame = nil
local Phase = "idle"
local CurrentSpawnIndex = 1
local IsFlying = false
local SpawnLoopRunning = false

local SavedStats = {
    WalkSpeed = nil,
    JumpPower = nil,
    JumpHeight = nil,
    UseJumpPower = nil,
    Humanoid = nil,
}

local StartFollow
local FlyTPToPosition
local StartAttackLoop
local SpawnLoop
local StopAttack
local InitialFlyAndStartLoop

-- ==================================================
-- GET HUMANOID
-- ==================================================
local function GetHumanoid()
    local Char = Player.Character
    if not Char then return nil, nil end
    local Hum = Char:FindFirstChildOfClass("Humanoid")
    local Root = Char:FindFirstChild("HumanoidRootPart")
    return Hum, Root
end

-- ==================================================
-- GET BAT SWING REMOTE
-- ==================================================
local function GetBatSwingRemote()
    local Success, Remote = pcall(function()
        return ReplicatedStorage.Packages.Networking["RE/BatSwing/Trigger"]
    end)
    if Success and Remote then return Remote end
    return nil
end

-- ==================================================
-- SAVE / RESTORE STATS
-- ==================================================
local function SaveLiveStats()
    local Hum = GetHumanoid()
    if not Hum then return end
    SavedStats.Humanoid = Hum
    SavedStats.WalkSpeed = Hum.WalkSpeed
    SavedStats.JumpPower = Hum.JumpPower
    SavedStats.JumpHeight = Hum.JumpHeight
    SavedStats.UseJumpPower = Hum.UseJumpPower
end

local function RestoreLiveStats()
    local Hum = GetHumanoid()
    if not Hum then return end
    if SavedStats.WalkSpeed ~= nil then pcall(function() Hum.WalkSpeed = SavedStats.WalkSpeed end) end
    if SavedStats.JumpPower ~= nil then pcall(function() Hum.JumpPower = SavedStats.JumpPower end) end
    if SavedStats.JumpHeight ~= nil then pcall(function() Hum.JumpHeight = SavedStats.JumpHeight end) end
    if SavedStats.UseJumpPower ~= nil then pcall(function() Hum.UseJumpPower = SavedStats.UseJumpPower end) end
end

local function EnsureStatsAlive()
    local Hum = GetHumanoid()
    if not Hum then return end
    if SavedStats.Humanoid ~= Hum then
        SavedStats.Humanoid = Hum
        SavedStats.WalkSpeed = Hum.WalkSpeed
        SavedStats.JumpPower = Hum.JumpPower
        SavedStats.JumpHeight = Hum.JumpHeight
        SavedStats.UseJumpPower = Hum.UseJumpPower
    end
end

-- ==================================================
-- CLEANUP
-- ==================================================
local function CleanupMovers()
    if FollowConnection then FollowConnection:Disconnect() FollowConnection = nil end
    if LockConnection then LockConnection:Disconnect() LockConnection = nil end
    if BodyVelocity then
        pcall(function()
            BodyVelocity.Velocity = Vector3.zero
            BodyVelocity.MaxForce = Vector3.zero
        end)
        BodyVelocity:Destroy()
        BodyVelocity = nil
    end
    if BodyGyro then
        pcall(function() BodyGyro.MaxTorque = Vector3.zero end)
        BodyGyro:Destroy()
        BodyGyro = nil
    end

    local Hum, Root = GetHumanoid()
    if Root then
        for _, Child in ipairs(Root:GetChildren()) do
            if Child.Name == "VoidcxzBV" or Child.Name == "VoidcxzBG" then
                pcall(function() Child:Destroy() end)
            end
        end
    end
    if Hum then
        pcall(function()
            Hum.PlatformStand = false
            Hum.Sit = false
        end)
    end
    if Root then
        pcall(function()
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    IsLocked = false
    LockCFrame = nil
end

-- ==================================================
-- GET POSITION / LOOK VECTOR
-- ==================================================
local function GetPosition(Object)
    if not Object then return nil end
    if Object:IsA("Model") then
        if Object.PrimaryPart then return Object.PrimaryPart.Position end
        local Part = Object:FindFirstChildWhichIsA("BasePart")
        if Part then return Part.Position end
        for _, Desc in ipairs(Object:GetDescendants()) do
            if Desc:IsA("BasePart") then return Desc.Position end
        end
    elseif Object:IsA("BasePart") then
        return Object.Position
    end
    return nil
end

local function GetLookVector(Object)
    if not Object then return Vector3.new(0, 0, -1) end
    local Part = nil
    if Object:IsA("Model") then
        Part = Object.PrimaryPart or Object:FindFirstChildWhichIsA("BasePart")
        if not Part then
            for _, Desc in ipairs(Object:GetDescendants()) do
                if Desc:IsA("BasePart") then Part = Desc break end
            end
        end
    elseif Object:IsA("BasePart") then
        Part = Object
    end
    if Part then return Part.CFrame.LookVector end
    return Vector3.new(0, 0, -1)
end

-- ==================================================
-- FIND ALL DRONES
-- ==================================================
local function FindAllDrones()
    local Container = workspace:FindFirstChild(CONTAINER_NAME)
    if not Container then return {} end
    local Drones = {}
    for _, obj in ipairs(Container:GetChildren()) do
        for _, prefix in ipairs(SEARCH_PREFIXES) do
            if string.sub(obj.Name, 1, #prefix) == prefix then
                table.insert(Drones, obj)
                break
            end
        end
    end
    return Drones
end

-- ==================================================
-- GET DRONE TIER / PRIORITY
-- ==================================================
local function GetDroneTier(Drone)
    if not Drone then return nil end
    local Tier = nil
    pcall(function() Tier = Drone:GetAttribute("ScrambleTier") end)
    return Tier
end

local function GetDronePriority(Drone)
    local Tier = GetDroneTier(Drone)
    if not Tier then return nil end
    return TIER_PRIORITY[Tier]
end

-- ==================================================
-- FIND BEST DRONE
-- ==================================================
local function FindBestDrone()
    local Drones = FindAllDrones()
    if #Drones == 0 then return nil end
    local CurrentSpawn = (CurrentSpawnIndex == 1) and SPAWN_POSITION_1 or SPAWN_POSITION_2
    local Best = nil
    local BestPriority = math.huge
    local BestDist = math.huge

    for _, Drone in ipairs(Drones) do
        local Priority = GetDronePriority(Drone)
        if Priority and Priority <= MAX_ALLOWED_PRIORITY then
            local Pos = GetPosition(Drone)
            if Pos then
                local Dist = math.floor((Pos - CurrentSpawn).Magnitude)
                if Priority < BestPriority or (Priority == BestPriority and Dist < BestDist) then
                    BestPriority = Priority
                    BestDist = Dist
                    Best = Drone
                end
            end
        end
    end
    return Best, BestPriority, BestDist
end

-- ==================================================
-- GET BEHIND POSITION
-- ==================================================
local function GetBehindPosition(Target)
    local TargetPos = GetPosition(Target)
    if not TargetPos then return nil end
    local LookVector = GetLookVector(Target)
    local BehindPos = TargetPos - (LookVector * FOLLOW_BEHIND_DISTANCE)
    BehindPos = Vector3.new(BehindPos.X, TargetPos.Y + 1, BehindPos.Z)
    return BehindPos
end

-- ==================================================
-- START LOCK
-- ==================================================
local function StartLock(Position, LookAt)
    LockCFrame = CFrame.new(Position, LookAt or (Position + Vector3.new(0, 0, -1)))
    if LockConnection then LockConnection:Disconnect() end
    IsLocked = true

    LockConnection = RunService.Heartbeat:Connect(function()
        if not AttackDroneEnabled then
            if LockConnection then LockConnection:Disconnect() LockConnection = nil end
            IsLocked = false
            return
        end
        local Hum, Root = GetHumanoid()
        if not Root then return end
        if CurrentTarget and CurrentTarget.Parent then
            local NewBehind = GetBehindPosition(CurrentTarget)
            local NewTargetPos = GetPosition(CurrentTarget)
            if NewBehind and NewTargetPos then
                LockCFrame = CFrame.new(NewBehind, NewTargetPos)
            end
        end
        Root.CFrame = LockCFrame
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero
    end)
end

-- ==================================================
-- FOLLOW BEHIND
-- ==================================================
function StartFollow()
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root then return end
    if Hum.Health <= 0 then return end

    Hum.PlatformStand = true

    BodyVelocity = Instance.new("BodyVelocity")
    BodyVelocity.Name = "VoidcxzBV"
    BodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    BodyVelocity.P = 1250
    BodyVelocity.Velocity = Vector3.zero
    BodyVelocity.Parent = Root

    BodyGyro = Instance.new("BodyGyro")
    BodyGyro.Name = "VoidcxzBG"
    BodyGyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
    BodyGyro.P = 3000
    BodyGyro.D = 500
    BodyGyro.CFrame = Root.CFrame
    BodyGyro.Parent = Root

    FollowConnection = RunService.Heartbeat:Connect(function()
        if not AttackDroneEnabled then CleanupMovers() return end
        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 then CleanupMovers() return end
        if Hum2.Health <= 0 then return end
        if not BodyVelocity or not BodyGyro then CleanupMovers() return end
        if not CurrentTarget or not CurrentTarget.Parent then CleanupMovers() return end

        local TargetPos = GetPosition(CurrentTarget)
        if not TargetPos then CleanupMovers() return end
        local BehindPos = GetBehindPosition(CurrentTarget)
        if not BehindPos then CleanupMovers() return end

        local CurrentPos = Root2.Position
        local Direction = BehindPos - CurrentPos
        local TotalDist = math.floor(Direction.Magnitude)

        if TotalDist <= SHORT_TP_DISTANCE then
            if BodyVelocity then
                BodyVelocity.Velocity = Vector3.zero
                BodyVelocity.MaxForce = Vector3.zero
            end
            if BodyGyro then
                BodyGyro.MaxTorque = Vector3.zero
            end

            task.wait(0.1)
            CleanupMovers()

            Root2.CFrame = CFrame.new(BehindPos, TargetPos)
            Root2.AssemblyLinearVelocity = Vector3.zero
            Root2.AssemblyAngularVelocity = Vector3.zero
            StartLock(BehindPos, TargetPos)
            return
        end

        BodyVelocity.Velocity = Direction.Unit * FOLLOW_SPEED
        BodyGyro.CFrame = CFrame.new(CurrentPos, TargetPos)
    end)
end

-- ==================================================
-- FLY TP TO POSITION
-- ==================================================
function FlyTPToPosition(Destination, Callback)
    CleanupMovers()
    IsFlying = true

    local Hum, Root = GetHumanoid()
    if not Hum or not Root then IsFlying = false if Callback then Callback() end return end
    if Hum.Health <= 0 then IsFlying = false if Callback then Callback() end return end

    Hum.PlatformStand = true

    BodyVelocity = Instance.new("BodyVelocity")
    BodyVelocity.Name = "VoidcxzBV"
    BodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    BodyVelocity.P = 1250
    BodyVelocity.Velocity = Vector3.zero
    BodyVelocity.Parent = Root

    BodyGyro = Instance.new("BodyGyro")
    BodyGyro.Name = "VoidcxzBG"
    BodyGyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
    BodyGyro.P = 3000
    BodyGyro.D = 500
    BodyGyro.CFrame = Root.CFrame
    BodyGyro.Parent = Root

    local StartTime = tick()

    FollowConnection = RunService.Heartbeat:Connect(function()
        if not AttackDroneEnabled then CleanupMovers() IsFlying = false return end
        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 then CleanupMovers() IsFlying = false return end
        if Hum2.Health <= 0 then return end
        if not BodyVelocity or not BodyGyro then CleanupMovers() IsFlying = false return end

        local CurrentPos = Root2.Position
        local Direction = Destination - CurrentPos
        local TotalDist = math.floor(Direction.Magnitude)

        if TotalDist <= 2 then
            if BodyVelocity then
                BodyVelocity.Velocity = Vector3.zero
                BodyVelocity.MaxForce = Vector3.zero
            end
            if BodyGyro then
                BodyGyro.MaxTorque = Vector3.zero
            end

            task.wait(0.1)
            CleanupMovers()
            IsFlying = false

            Root2.CFrame = CFrame.new(Destination)
            Root2.AssemblyLinearVelocity = Vector3.zero
            Root2.AssemblyAngularVelocity = Vector3.zero

            if Callback then Callback() end
            return
        end

        if tick() - StartTime > ARRIVE_TIMEOUT then
            CleanupMovers()
            IsFlying = false
            if Callback then Callback() end
            return
        end

        BodyVelocity.Velocity = Direction.Unit * FOLLOW_SPEED
        BodyGyro.CFrame = CFrame.new(CurrentPos, Destination)
    end)
end

-- ==================================================
-- STOP ATTACK
-- ==================================================
function StopAttack()
    print("[AttackDrone] Stop Attack")
    CleanupMovers()
    CurrentTarget = nil
    CurrentTargetPriority = nil
    SpawnLoopRunning = false
end

-- ==================================================
-- SPAWN LOOP
-- ==================================================
function SpawnLoop()
    if SpawnLoopRunning then return end
    SpawnLoopRunning = true

    task.spawn(function()
        while AttackDroneEnabled do
            local CurrentSpawn = (CurrentSpawnIndex == 1) and SPAWN_POSITION_1 or SPAWN_POSITION_2

            if CurrentTarget and CurrentTarget.Parent then
                task.wait(0.5)
                continue
            end

            print("[AttackDrone] Flying to Spawn " .. CurrentSpawnIndex)

            local Arrived = false
            FlyTPToPosition(CurrentSpawn, function() Arrived = true end)

            local WaitTime = 0
            while AttackDroneEnabled and not Arrived and WaitTime < ARRIVE_TIMEOUT do
                task.wait(0.1)
                WaitTime = WaitTime + 0.1
            end

            if not AttackDroneEnabled then break end
            task.wait(SPAWN_WAIT_TIME)
            if not AttackDroneEnabled then break end

            local Found = FindBestDrone()
            if Found and Found.Parent then
                print("[AttackDrone] Found Mob Top " .. tostring(GetDronePriority(Found)) .. " at Spawn " .. CurrentSpawnIndex)
                CurrentTarget = Found
                StartFollow()
                while AttackDroneEnabled and CurrentTarget and CurrentTarget.Parent do
                    task.wait(0.5)
                end
                print("[AttackDrone] Mob Cleared → Return to Spawn 1")
                CurrentSpawnIndex = 1
            else
                print("[AttackDrone] No Top 1/2/3 Mob at Spawn " .. CurrentSpawnIndex .. " → Switch")
                CurrentSpawnIndex = (CurrentSpawnIndex == 1) and 2 or 1
            end

            task.wait(0.2)
        end
        SpawnLoopRunning = false
    end)
end

-- ==================================================
-- FIRE REMOTE
-- ==================================================
local function FireAtDrone(Drone)
    if not Drone or not Drone.Parent then return end

    local isDrone = false
    for _, prefix in ipairs(SEARCH_PREFIXES) do
        if string.sub(Drone.Name, 1, #prefix) == prefix then
            isDrone = true
            break
        end
    end
    if not isDrone then return end

    local Remote = GetBatSwingRemote()
    if not Remote then return end

    local Hum, Root = GetHumanoid()
    if not Root then return end

    local DronePos = GetPosition(Drone)
    if not DronePos then return end

    local Dist = math.floor((DronePos - Root.Position).Magnitude)
    if Dist > ATTACK_RANGE then return end

    TraceSequence = TraceSequence + 1
    local TraceId = tostring(Player.UserId) .. ":" .. tostring(TraceSequence) .. ":" .. tostring(math.floor(workspace:GetServerTimeNow() * 1000))

    pcall(function() Remote:FireServer(Drone, TraceId) end)
end

-- ==================================================
-- MAIN ATTACK LOOP
-- ==================================================
function StartAttackLoop()
    if AttackConnection then AttackConnection:Disconnect() AttackConnection = nil end

    AttackConnection = RunService.Heartbeat:Connect(function()
        if not AttackDroneEnabled then return end
        if IsFlying then return end

        local Hum, Root = GetHumanoid()
        if not Hum or not Root then return end
        if Hum.Health <= 0 then return end

        EnsureStatsAlive()

        if not CurrentTarget or not CurrentTarget.Parent then
            local NewTarget, NewPriority = FindBestDrone()
            if NewTarget then
                CurrentTarget = NewTarget
                CurrentTargetPriority = NewPriority
                StartFollow()
            end
            return
        end

        local CurrentPriority = GetDronePriority(CurrentTarget)
        local BestDrone, BestPriority = FindBestDrone()

        if BestDrone and BestPriority and CurrentPriority and BestPriority < CurrentPriority then
            print("[AttackDrone] Higher Priority Detected! Switching...")
            CurrentTarget = BestDrone
            CurrentTargetPriority = BestPriority
            StartFollow()
            return
        end

        local now = tick()
        if now - LastFire >= ATTACK_INTERVAL then
            LastFire = now
            FireAtDrone(CurrentTarget)
        end
    end)
end

-- ==================================================
-- INITIAL FLY (Logic ចាស់ — Signed X Distance)
-- ==================================================
function InitialFlyAndStartLoop()
    local Hum, Root = GetHumanoid()
    if not Root then return end

    local PlayerPos = Root.Position
    local PlayerToPoint1Signed = math.floor(PlayerPos.X - POINT_1.X)

    print("========================================")
    print("[AttackDrone] Initial Fly Decision (Signed X)")
    print("  Player Pos:                       ", PlayerPos)
    print("  Signed (Player.X - Point1.X):     ", PlayerToPoint1Signed)
    print("========================================")

    if PlayerToPoint1Signed > 0 then
        print("[AttackDrone] → Signed > 0 (Player in FRONT) → Fly to Spawn 1")
        CurrentSpawnIndex = 1
        SpawnLoop()
    else
        print("[AttackDrone] → Signed <= 0 (Player at/behind) → Fly to Safe first")
        local SafeArrived = false
        FlyTPToPosition(SAFE_ZONE, function()
            SafeArrived = true
            print("[AttackDrone] ✅ Arrived at Safe Zone")
        end)

        local WaitTime = 0
        while AttackDroneEnabled and not SafeArrived and WaitTime < ARRIVE_TIMEOUT do
            task.wait(0.1)
            WaitTime = WaitTime + 0.1
        end

        if not AttackDroneEnabled then return end
        task.wait(SAFE_WAIT_TIME)
        print("[AttackDrone] Safe Zone Reached → Start Spawn Loop")
        CurrentSpawnIndex = 1
        SpawnLoop()
    end
end

-- ==================================================
-- START / STOP
-- ==================================================
local function StartAttack()
    if AttackDroneEnabled then return end
    AttackDroneEnabled = true

    SaveLiveStats()

    if _G.VOIDCXZ_AutoAttack then
        _G.VOIDCXZ_AutoAttack.EnableAutoEquip()
    end

    StartAttackLoop()

    print("[AttackDrone] Attack Drone: ON (Initial Fly Logic — Signed X)")

    task.spawn(function()
        InitialFlyAndStartLoop()
    end)
end

local function StopAttackDrone()
    if not AttackDroneEnabled then return end
    AttackDroneEnabled = false

    if AttackConnection then AttackConnection:Disconnect() AttackConnection = nil end

    CleanupMovers()
    CurrentTarget = nil
    CurrentTargetPriority = nil
    CurrentSpawnIndex = 1
    IsFlying = false
    SpawnLoopRunning = false

    RestoreLiveStats()

    if _G.VOIDCXZ_AutoAttack then
        _G.VOIDCXZ_AutoAttack.DisableAutoEquip()
    end

    local Hum, Root = GetHumanoid()
    if Root then
        pcall(function()
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
    end

    print("[AttackDrone] Attack Drone: OFF")
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_AttackDrone = {
    Start = StartAttack,
    Stop = StopAttackDrone,
    Enable = StartAttack,
    Disable = StopAttackDrone,
    Toggle = function()
        if AttackDroneEnabled then StopAttackDrone() else StartAttack() end
    end,
    IsEnabled = function() return AttackDroneEnabled end,
    StopAttack = StopAttack,
    SpawnLoop = SpawnLoop,
    InitialFlyAndStartLoop = InitialFlyAndStartLoop,
    FindAllDrones = FindAllDrones,
    FindBestDrone = FindBestDrone,
    GetDronePriority = GetDronePriority,
    GetBatSwingRemote = GetBatSwingRemote,
    GetSavedStats = function() return SavedStats end,
    SPAWN_POSITION_1 = SPAWN_POSITION_1,
    SPAWN_POSITION_2 = SPAWN_POSITION_2,
    SAFE_ZONE = SAFE_ZONE,
    POINT_1 = POINT_1,
    TIER_PRIORITY = TIER_PRIORITY,
    MAX_ALLOWED_PRIORITY = MAX_ALLOWED_PRIORITY,
    FOLLOW_SPEED = FOLLOW_SPEED
}

print("✅ AttackDrone Feature Loaded (Logic ចាស់ទាំងស្រុង + Register)")
]]
__VOIDCXZ_SOURCE[[[Features/AutoAttack.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Auto Attack
-- Auto Equip Bat + Auto Fire Remote (Range 17 + Fast)
-- ✅ Register ជាមួយ CharacterSystem
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Player = Players.LocalPlayer
local Backpack = Player:WaitForChild("Backpack")

-- ==================================================
-- FIND REMOTE
-- ==================================================
local function GetBatSwingRemote()
    local Success, Remote = pcall(function()
        return ReplicatedStorage.Packages.Networking["RE/BatSwing/Trigger"]
    end)
    if Success and Remote then
        return Remote
    end
    return nil
end

-- ==================================================
-- SETTINGS
-- ==================================================
local ATTACK_RANGE = 60
local FIRE_INTERVAL = 0.01

-- ==================================================
-- STATE
-- ==================================================
local AutoEquipEnabled = false
local AutoHitEnabled = false
local EquipConnection = nil
local HitConnection = nil
local CurrentBat = nil
local LastFire = 0
local TraceSequence = 0

-- ==================================================
-- GET HUMANOID
-- ==================================================
local function GetHumanoid()
    local Char = Player.Character
    if not Char then return nil, nil end
    local Hum = Char:FindFirstChildOfClass("Humanoid")
    local Root = Char:FindFirstChild("HumanoidRootPart")
    return Hum, Root
end

-- ==================================================
-- FIND BAT TOOL
-- ==================================================
local function FindBatTool()
    for _, tool in ipairs(Backpack:GetChildren()) do
        if tool:IsA("Tool") then
            if tool.ToolTip == "Bat" or tool.Name:find("Bat") then
                return tool
            end
        end
    end
    local Char = Player.Character
    if Char then
        for _, tool in ipairs(Char:GetChildren()) do
            if tool:IsA("Tool") then
                if tool.ToolTip == "Bat" or tool.Name:find("Bat") then
                    return tool
                end
            end
        end
    end
    return nil
end

-- ==================================================
-- FEATURE 1: AUTO EQUIP BAT
-- ==================================================
local function EquipBat()
    local Bat = FindBatTool()
    if not Bat then return false end
    if Bat.Parent == Backpack then
        local Hum, Root = GetHumanoid()
        if Hum then
            Hum:EquipTool(Bat)
            CurrentBat = Bat
            return true
        end
    elseif Bat.Parent == Player.Character then
        CurrentBat = Bat
        return true
    end
    return false
end

local function EnableAutoEquip()
    if AutoEquipEnabled then return end
    AutoEquipEnabled = true
    if EquipConnection then
        EquipConnection:Disconnect()
        EquipConnection = nil
    end
    EquipConnection = RunService.Heartbeat:Connect(function()
        if not AutoEquipEnabled then return end
        local Bat = FindBatTool()
        if Bat and Bat.Parent == Backpack then
            EquipBat()
        end
    end)
    EquipBat()
    print("[VOIDCXZ] Auto Equip Bat: ON")
end

local function DisableAutoEquip()
    if not AutoEquipEnabled then return end
    AutoEquipEnabled = false
    if EquipConnection then
        EquipConnection:Disconnect()
        EquipConnection = nil
    end
    print("[VOIDCXZ] Auto Equip Bat: OFF")
end

local function ToggleAutoEquip()
    if AutoEquipEnabled then DisableAutoEquip() else EnableAutoEquip() end
end

-- ==================================================
-- FEATURE 2: AUTO FIRE REMOTE
-- ==================================================
local function FindClosestPlayer()
    local Hum, Root = GetHumanoid()
    if not Root then return nil end
    
    local Closest = nil
    local ClosestDist = ATTACK_RANGE
    
    for _, otherPlayer in ipairs(Players:GetPlayers()) do
        if otherPlayer ~= Player then
            local otherChar = otherPlayer.Character
            if otherChar then
                local otherHum = otherChar:FindFirstChildOfClass("Humanoid")
                local otherRoot = otherChar:FindFirstChild("HumanoidRootPart")
                if otherHum and otherRoot and otherHum.Health > 0 then
                    local Dist = (otherRoot.Position - Root.Position).Magnitude
                    if Dist < ClosestDist then
                        ClosestDist = Dist
                        Closest = otherPlayer
                    end
                end
            end
        end
    end
    return Closest
end

local function FireRemote()
    local Target = FindClosestPlayer()
    if not Target then return end
    
    local Remote = GetBatSwingRemote()
    if not Remote then return end
    
    TraceSequence = TraceSequence + 1
    local TraceId = tostring(Player.UserId) .. ":" .. tostring(TraceSequence) .. ":" .. tostring(math.floor(workspace:GetServerTimeNow() * 1000))
    
    pcall(function()
        Remote:FireServer(Target, TraceId)
    end)
end

local function EnableAutoHit()
    if AutoHitEnabled then return end
    AutoHitEnabled = true
    if HitConnection then
        HitConnection:Disconnect()
        HitConnection = nil
    end
    HitConnection = RunService.Heartbeat:Connect(function()
        if not AutoHitEnabled then return end
        local now = tick()
        if now - LastFire < FIRE_INTERVAL then return end
        LastFire = now
        FireRemote()
    end)
    print("[VOIDCXZ] Auto Fire Remote (Range 17 + Fast): ON")
end

local function DisableAutoHit()
    if not AutoHitEnabled then return end
    AutoHitEnabled = false
    if HitConnection then
        HitConnection:Disconnect()
        HitConnection = nil
    end
    print("[VOIDCXZ] Auto Fire Remote: OFF")
end

local function ToggleAutoHit()
    if AutoHitEnabled then DisableAutoHit() else EnableAutoHit() end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_AutoAttack = {
    ToggleAutoEquip = ToggleAutoEquip,
    EnableAutoEquip = EnableAutoEquip,
    DisableAutoEquip = DisableAutoEquip,
    IsAutoEquipEnabled = function() return AutoEquipEnabled end,
    ToggleAutoHit = ToggleAutoHit,
    EnableAutoHit = EnableAutoHit,
    DisableAutoHit = DisableAutoHit,
    IsAutoHitEnabled = function() return AutoHitEnabled end,
    FindBatTool = FindBatTool,
    GetBatSwingRemote = GetBatSwingRemote,
    FindClosestPlayer = FindClosestPlayer
}


print("✅ AutoAttack Feature Loaded (Range 17 + Fast + Register)")
]]
__VOIDCXZ_SOURCE[[[Features/AutoFarm.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Auto Farm (FAST)
-- ✅ Cache PetData + UidCategory → លឿន
-- ✅ ភ្ជាប់ជាមួយ TeleportSystem ថ្មី (Walk TP + Shot TP)
-- ✅ Disable VIPTP ពេល StartTeleport (ការពារជាន់គ្នា)
-- ==================================================

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Player = Players.LocalPlayer
local Container = workspace:WaitForChild("AreaEggSlotsClient")

--==================================================
-- CACHE SYSTEM
--==================================================
local Cache = {
    MeshIdMap = {},
    MeshIdMapBuilt = false,
    PetData = {},
    UidCategory = {},
}

local AutoFarmEnabled = false
local SelectedEgg = nil
local EggList = {}

--==================================================
-- ASSETS
--==================================================
local Assets = ReplicatedStorage:WaitForChild("Data"):WaitForChild("Assets")
local Configs = Assets:WaitForChild("Configs")
local EggModels = ReplicatedStorage:WaitForChild("Assets"):WaitForChild("Models"):WaitForChild("Eggs")

--==================================================
-- MUTATIONS MODULE (CACHE)
--==================================================
local MutationsModule = nil
pcall(function()
    MutationsModule = require(ReplicatedStorage.Shared.Modules.Mutations)
end)

--==================================================
-- BUILD MESHID MAP (ម្ដងគត់)
--==================================================
local function BuildMeshIdMap()
    if Cache.MeshIdMapBuilt then return end

    for _, Config in ipairs(Configs:GetChildren()) do
        local Success, Module = pcall(function()
            return require(Config)
        end)
        if Success and Module and Module.Egg then
            local ModelName = Module.Egg.ModelName or Config.Name
            local EggTemplate = EggModels:FindFirstChild(ModelName)
            if EggTemplate then
                for _, descendant in ipairs(EggTemplate:GetDescendants()) do
                    if descendant:IsA("MeshPart") and descendant.MeshId ~= "" then
                        Cache.MeshIdMap[descendant.MeshId] = Config.Name
                    end
                    if descendant:IsA("SpecialMesh") and descendant.MeshId ~= "" then
                        Cache.MeshIdMap[descendant.MeshId] = Config.Name
                    end
                end
            end
        end
    end

    Cache.MeshIdMapBuilt = true
    print("[AutoFarm] MeshId Map Built (Cache)")
end

BuildMeshIdMap()

--==================================================
-- GET PET DATA (CACHE)
--==================================================
local function GetPetData(AssetCategory)
    if not AssetCategory then return nil end

    if Cache.PetData[AssetCategory] then
        return Cache.PetData[AssetCategory]
    end

    local Config = Configs:FindFirstChild(AssetCategory)
    if not Config then return nil end

    local Data = {
        Name = AssetCategory,
        DisplayName = AssetCategory,
        EarningRate = 0,
        Icon = nil
    }

    local Success, Module = pcall(function()
        return require(Config)
    end)

    if Success and Module then
        Data.DisplayName = Module.DisplayName or AssetCategory
        Data.EarningRate = Module.EarningRate or 0
        Data.Icon = Module.Icon
    end

    Cache.PetData[AssetCategory] = Data
    return Data
end

--==================================================
-- FORMAT MONEY
--==================================================
local function FormatMoney(Amount)
    if type(Amount) ~= "number" then return tostring(Amount) end
    if Amount >= 1e12 then
        return string.format("%.2fT", Amount / 1e12)
    elseif Amount >= 1e9 then
        return string.format("%.2fB", Amount / 1e9)
    elseif Amount >= 1e6 then
        return string.format("%.2fM", Amount / 1e6)
    elseif Amount >= 1e3 then
        return string.format("%.2fK", Amount / 1e3)
    else
        return tostring(math.floor(Amount))
    end
end

--==================================================
-- CALCULATE REAL RATE (CACHE MUTATIONS)
--==================================================
local function CalculateRatePerSecond(EarningRate, Scale, Mutations)
    local PayoutFactor
    if Scale <= 5 then
        PayoutFactor = Scale ^ 1.85
    else
        PayoutFactor = (Scale / 5) ^ 1.2 * 19.637875755794113
    end

    local MutationMultiplier = 1
    if Mutations and #Mutations > 0 and MutationsModule then
        local Success, Result = pcall(function()
            return MutationsModule.EarningsFor(Mutations)
        end)
        if Success then
            MutationMultiplier = Result
        end
    end

    return math.round(EarningRate * PayoutFactor * MutationMultiplier)
end

--==================================================
-- FIND ASSET CATEGORY (CACHE Uid)
--==================================================
local function FindAssetCategory(EggModel)
    if not EggModel then return nil end

    local Uid = EggModel.Name
    if Cache.UidCategory[Uid] then
        return Cache.UidCategory[Uid]
    end

    for _, descendant in ipairs(EggModel:GetDescendants()) do
        if descendant:IsA("MeshPart") and descendant.MeshId ~= "" then
            local Category = Cache.MeshIdMap[descendant.MeshId]
            if Category then
                Cache.UidCategory[Uid] = Category
                return Category
            end
        end
        if descendant:IsA("SpecialMesh") and descendant.MeshId ~= "" then
            local Category = Cache.MeshIdMap[descendant.MeshId]
            if Category then
                Cache.UidCategory[Uid] = Category
                return Category
            end
        end
    end
    return nil
end

--==================================================
-- SCAN EGGS (FAST)
--==================================================
local function ScanEggs()
    EggList = {}

    for _, child in ipairs(Container:GetChildren()) do
        if child:IsA("Model") then
            local AssetCategory = FindAssetCategory(child)
            if AssetCategory then
                local Data = GetPetData(AssetCategory)
                if Data then
                    local Scale = child:GetAttribute("AssetScale") or 1
                    local Mutations = child:GetAttribute("Mutations") or {}
                    local RealRate = CalculateRatePerSecond(Data.EarningRate, Scale, Mutations)

                    table.insert(EggList, {
                        Id = child.Name,
                        Category = AssetCategory,
                        DisplayName = Data.DisplayName,
                        Icon = Data.Icon,
                        EarningRate = RealRate,
                        Model = child
                    })
                end
            end
        end
    end

    table.sort(EggList, function(a, b)
        return a.EarningRate > b.EarningRate
    end)

    return EggList
end

--==================================================
-- ENABLE / DISABLE
--==================================================
local function EnableAutoFarm()
    AutoFarmEnabled = true
    print("[VOIDCXZ] Auto Farm: ON")
end

local function DisableAutoFarm()
    AutoFarmEnabled = false
    print("[VOIDCXZ] Auto Farm: OFF")
end

--==================================================
-- SELECT EGG
--==================================================
local function SelectEgg(EggData)
    SelectedEgg = EggData
    print("[VOIDCXZ] Selected Egg: " .. EggData.DisplayName .. " ($" .. FormatMoney(EggData.EarningRate) .. "/s)")
end

--==================================================
-- ✅ START TELEPORT (Disable VIPTP មុន)
--==================================================
local function StartTeleport()
    if not SelectedEgg then
        warn("[VOIDCXZ] No Egg Selected")
        return
    end

    -- ✅ Disable VIPTP (Tab Farming) មុន
    if _G.VOIDCXZ_VIPTP and _G.VOIDCXZ_VIPTP.IsEnabled() then
        pcall(function()
            _G.VOIDCXZ_VIPTP.Disable()
        end)
        print("[AutoFarm] ✅ Disabled VIPTP (Prevent Conflict)")
    end

    print("[VOIDCXZ] Start Teleport | Target: " .. SelectedEgg.Id)

    if _G.VOIDCXZ_TeleportSystem then
        _G.VOIDCXZ_TeleportSystem.SetTargetId(SelectedEgg.Id)
        _G.VOIDCXZ_TeleportSystem.Enable()
        print("[VOIDCXZ] ✅ TeleportSystem Enabled")
    else
        warn("[VOIDCXZ] TeleportSystem not loaded!")
    end
end

--==================================================
-- STOP TELEPORT
--==================================================
local function StopTeleport()
    if _G.VOIDCXZ_TeleportSystem then
        _G.VOIDCXZ_TeleportSystem.Disable()
    end
    print("[VOIDCXZ] Stop Teleport")
end

--==================================================
-- EXPORT
--==================================================
_G.VOIDCXZ_AutoFarm = {
    Enable = EnableAutoFarm,
    Disable = DisableAutoFarm,
    IsEnabled = function() return AutoFarmEnabled end,
    ScanEggs = ScanEggs,
    GetEggList = function() return EggList end,
    SelectEgg = SelectEgg,
    StartTeleport = StartTeleport,
    StopTeleport = StopTeleport,
    GetSelectedEgg = function() return SelectedEgg end,
    FormatMoney = FormatMoney,

    ClearCache = function()
        Cache.UidCategory = {}
        print("[AutoFarm] Uid Cache Cleared")
    end,
}

--==================================================
-- REGISTER
--==================================================
if _G.VOIDCXZ_CharacterSystem then
    _G.VOIDCXZ_CharacterSystem:RegisterFeature({
        Name = "AutoFarm",
        Enable = EnableAutoFarm,
        Disable = DisableAutoFarm,
        IsEnabled = function() return AutoFarmEnabled end,
        OnCharacterAdded = function(Char, Hum, Root)
            if AutoFarmEnabled and SelectedEgg then
                task.wait(2)
                pcall(function()
                    if _G.VOIDCXZ_TeleportSystem and _G.VOIDCXZ_TeleportSystem.IsEnabled() then
                        StartTeleport()
                    end
                end)
            end
        end
    })
end

print("✅ AutoFarm Feature Loaded (FAST + CACHE + TeleportSystem + No Conflict)")
]]
__VOIDCXZ_SOURCE[[[Features/BypassAntiCheat.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Bypass Anti Cheat
-- Humanoid Replace + Anti Death
-- ✅ Re-apply ពេល Player Died + CharacterAdded
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Player = Players.LocalPlayer

-- ==================================================
-- STATE
-- ==================================================
local BypassEnabled = true
local ReapplyThread = nil
local DiedConnection = nil
local CharacterConnection = nil

-- ==================================================
-- MAIN FUNCTION
-- ==================================================
local function RunBypassAntiCheat()
    local Character = Player.Character
    if not Character then return end

    local OldHumanoid = Character:FindFirstChildOfClass("Humanoid")
    if not OldHumanoid then
        warn("[VOIDCXZ] Humanoid not found")
        return
    end

    -- ✅ Check បើ Humanoid ត្រូវ Replace រួចហើយ
    local ExistingBypass = OldHumanoid:GetAttribute("VoidcxzBypass")
    if ExistingBypass then
        print("[VOIDCXZ] Bypass already applied → Skip")
        return
    end

    print("========================================")
    print("[VOIDCXZ] START HUMANOID REPLACE")
    print("========================================")

    -- ANTI DEATH SETTINGS
    local GodMode = true

    -- SAVE JUMP PROPERTIES
    local SavedJumpProperties = {}

    local function SaveJumpProperty(Property)
        local Success, Value = pcall(function()
            return OldHumanoid[Property]
        end)
        if Success then
            SavedJumpProperties[Property] = Value
        end
    end

    SaveJumpProperty("JumpPower")
    SaveJumpProperty("JumpHeight")
    SaveJumpProperty("UseJumpPower")

    -- SAVE STATE MACHINE
    local SavedEvaluateStateMachine
    pcall(function()
        SavedEvaluateStateMachine = OldHumanoid.EvaluateStateMachine
    end)

    -- SAVE ALL HUMANOID STATE SETTINGS
    local SavedStates = {}
    local States = {
        Enum.HumanoidStateType.FallingDown,
        Enum.HumanoidStateType.Running,
        Enum.HumanoidStateType.RunningNoPhysics,
        Enum.HumanoidStateType.Climbing,
        Enum.HumanoidStateType.StrafingNoPhysics,
        Enum.HumanoidStateType.Ragdoll,
        Enum.HumanoidStateType.GettingUp,
        Enum.HumanoidStateType.Jumping,
        Enum.HumanoidStateType.Landed,
        Enum.HumanoidStateType.Flying,
        Enum.HumanoidStateType.Freefall,
        Enum.HumanoidStateType.Seated,
        Enum.HumanoidStateType.PlatformStanding,
        Enum.HumanoidStateType.Dead,
        Enum.HumanoidStateType.Swimming,
        Enum.HumanoidStateType.Physics,
    }

    for _, State in ipairs(States) do
        local Success, Enabled = pcall(function()
            return OldHumanoid:GetStateEnabled(State)
        end)
        if Success then
            SavedStates[State] = Enabled
        end
    end

    -- CLONE HUMANOID
    local NewHumanoid = OldHumanoid:Clone()
    if not NewHumanoid then
        warn("[VOIDCXZ] Failed to clone Humanoid")
        return
    end
    NewHumanoid.Name = OldHumanoid.Name

    -- ✅ Set Attribute ដើម្បីកុំឲ្យ Re-apply ច្រើនដង
    NewHumanoid:SetAttribute("VoidcxzBypass", true)

    -- MOVE HUMANOID CHILDREN
    for _, Child in ipairs(OldHumanoid:GetChildren()) do
        local ExistingCloneChild = NewHumanoid:FindFirstChild(Child.Name)
        if ExistingCloneChild then
            pcall(function()
                ExistingCloneChild:Destroy()
            end)
        end
        pcall(function()
            Child.Parent = NewHumanoid
        end)
    end

    -- REPLACEMENT ORDER
    OldHumanoid:Destroy()
    task.wait()
    NewHumanoid.Parent = Character
    task.wait()

    if not NewHumanoid.Parent then
        warn("[VOIDCXZ] New Humanoid was removed")
        return
    end

    print("[VOIDCXZ] New Humanoid:", NewHumanoid)

    -- UPDATE CHARACTER SYSTEM
    if _G.VOIDCXZ_CharacterSystem then
        _G.VOIDCXZ_CharacterSystem.CurrentHumanoid = NewHumanoid
        _G.VOIDCXZ_CharacterSystem.CurrentRoot = Character:FindFirstChild("HumanoidRootPart")
        print("[VOIDCXZ] CharacterSystem Updated with New Humanoid")
    end

    -- RESTORE JUMP PROPERTIES
    pcall(function()
        NewHumanoid.UseJumpPower = SavedJumpProperties.UseJumpPower
    end)
    pcall(function()
        NewHumanoid.JumpPower = SavedJumpProperties.JumpPower
    end)
    pcall(function()
        NewHumanoid.JumpHeight = SavedJumpProperties.JumpHeight
    end)

    -- RESTORE EVALUATE STATE MACHINE
    pcall(function()
        if SavedEvaluateStateMachine ~= nil then
            NewHumanoid.EvaluateStateMachine = SavedEvaluateStateMachine
        end
    end)

    -- RESTORE HUMANOID STATE SETTINGS
    for State, Enabled in pairs(SavedStates) do
        pcall(function()
            NewHumanoid:SetStateEnabled(State, Enabled)
        end)
    end

    -- ENSURE ANIMATOR
    local Animator = NewHumanoid:FindFirstChildOfClass("Animator")
    if not Animator then
        Animator = Instance.new("Animator")
        Animator.Parent = NewHumanoid
    end

    -- RESTART ANIMATE
    local Animate = Character:FindFirstChild("Animate")
    if Animate then
        pcall(function()
            Animate.Disabled = true
        end)
        task.wait()
        pcall(function()
            Animate.Disabled = false
        end)
    end

    task.wait(0.1)

    -- ANTI DEATH FUNCTIONS
    local function LockHealth()
        if GodMode and NewHumanoid and NewHumanoid.Parent then
            pcall(function()
                NewHumanoid.MaxHealth = math.huge
                NewHumanoid.Health = math.huge
            end)
        end
    end

    local function BlockDeathState()
        if not NewHumanoid or not NewHumanoid.Parent then return end
        pcall(function()
            NewHumanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        end)
        pcall(function()
            NewHumanoid.BreakJointsOnDeath = false
        end)
        pcall(function()
            NewHumanoid.RequiresNeck = false
        end)
    end

    local function BindAntiDeath(Humanoid)
        if not Humanoid then return end
        Humanoid.HealthChanged:Connect(function(Health)
            if GodMode and Humanoid and Humanoid.Parent then
                if Health < Humanoid.MaxHealth then
                    pcall(function()
                        Humanoid.Health = Humanoid.MaxHealth
                    end)
                end
            end
        end)
        Humanoid.Died:Connect(function()
            if GodMode and Humanoid and Humanoid.Parent then
                pcall(function()
                    Humanoid.Health = Humanoid.MaxHealth
                end)
            end
        end)
    end

    LockHealth()
    BlockDeathState()
    BindAntiDeath(NewHumanoid)

    -- GOD MODE LOOP
    task.spawn(function()
        while BypassEnabled do
            task.wait(0.1)
            if GodMode and NewHumanoid and NewHumanoid.Parent then
                pcall(function()
                    if NewHumanoid.Health < NewHumanoid.MaxHealth then
                        NewHumanoid.Health = NewHumanoid.MaxHealth
                    end
                    NewHumanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
                end)
            end
        end
    end)

    -- CONTROL MODULE REFRESH
    local function RefreshControls()
        local PlayerScripts = Player:FindFirstChild("PlayerScripts")
        if not PlayerScripts then return end
        local PlayerModule = PlayerScripts:FindFirstChild("PlayerModule")
        if not PlayerModule then return end
        local Success, Module = pcall(function()
            return require(PlayerModule)
        end)
        if not Success or not Module then return end
        local Controls
        pcall(function()
            Controls = Module:GetControls()
        end)
        if not Controls then return end
        pcall(function()
            Controls:OnCharacterAdded(Character)
        end)
        task.wait()
        pcall(function()
            Controls:UpdateActiveControlModuleEnabled()
        end)
    end

    RefreshControls()

    -- CAMERA
    pcall(function()
        local Camera = workspace.CurrentCamera
        if Camera then
            Camera.CameraSubject = NewHumanoid
        end
    end)

    -- ✅ RESTART FEATURES តាមរយៈ CHARACTER SYSTEM
    if _G.VOIDCXZ_CharacterSystem then
        task.spawn(function()
            task.wait(0.3)
            _G.VOIDCXZ_CharacterSystem:RestartAllFeatures()
        end)
    end

    print("")
    print("========================================")
    print("[VOIDCXZ] HUMANOID REPLACE + ANTI DEATH COMPLETE")
    print("========================================")
end

-- ==================================================
-- ✅ SETUP DIED LISTENER (ភ្ជាប់ឡើងវិញពេល Player ស្លាប់)
-- ==================================================
local function SetupDiedListener(Humanoid)
    if not Humanoid then return end

    if DiedConnection then
        DiedConnection:Disconnect()
        DiedConnection = nil
    end

    DiedConnection = Humanoid.Died:Connect(function()
        print("[VOIDCXZ] ⚠️ Player Died → Re-apply Bypass")

        -- ✅ រង់ចាំ 0.5s ឲ្យ Character ថ្មី Load
        task.wait(0.5)

        -- ✅ Re-apply Bypass
        task.spawn(function()
            RunBypassAntiCheat()
        end)
    end)

    print("[VOIDCXZ] Died Listener Setup")
end

-- ==================================================
-- ✅ SETUP CHARACTER ADDED LISTENER
-- ==================================================
local function SetupCharacterListener()
    if CharacterConnection then
        CharacterConnection:Disconnect()
        CharacterConnection = nil
    end

    CharacterConnection = Player.CharacterAdded:Connect(function(Character)
        print("[VOIDCXZ] Character Added → Re-apply Bypass")

        task.wait(1)

        -- ✅ Setup Died Listener សម្រាប់ Humanoid ថ្មី
        local Hum = Character:FindFirstChildOfClass("Humanoid")
        if Hum then
            SetupDiedListener(Hum)
        end

        -- ✅ Re-apply Bypass
        RunBypassAntiCheat()
    end)
end

-- ==================================================
-- ✅ SETUP DEATH LISTENER (Player Died)
-- ==================================================
local function SetupHumanoidDiedCheck()
    task.spawn(function()
        while BypassEnabled do
            task.wait(1)

            local Char = Player.Character
            if Char then
                local Hum = Char:FindFirstChildOfClass("Humanoid")
                if Hum then
                    -- ✅ Check បើមិនទាន់ Setup Died Listener
                    if not DiedConnection or not DiedConnection.Connected then
                        SetupDiedListener(Hum)
                    end
                end
            end
        end
    end)
end

-- ==================================================
-- RUN IMMEDIATELY
-- ==================================================
task.spawn(function()
    task.wait(2)
    RunBypassAntiCheat()

    -- ✅ Setup Listeners
    SetupCharacterListener()
    SetupHumanoidDiedCheck()

    -- ✅ Setup Died Listener សម្រាប់ Humanoid បច្ចុប្បន្ន
    local Char = Player.Character
    if Char then
        local Hum = Char:FindFirstChildOfClass("Humanoid")
        if Hum then
            SetupDiedListener(Hum)
        end
    end
end)

print("✅ BypassAntiCheat Feature Loaded (Died Re-apply)")
]]
__VOIDCXZ_SOURCE[[[Features/ConfigSystem.lua]]] = [[--==================================================
-- VOIDCXZ HUB - CONFIG SYSTEM (EMPTY)
-- ✅ ដក AttackDroneEnabled + SafeSpeedMode ចេញទាំងស្រុង
-- ✅ គ្មាន Save/Load អ្វីទេ
-- Folder: VOIDCXZ-SAE
-- File: yokudo.json
--==================================================

local HttpService = game:GetService("HttpService")

local CONFIG_FOLDER = "VOIDCXZ-SAE"
local CONFIG_FILE = CONFIG_FOLDER .. "/yokudo.json"

--==================================================
-- DEFAULT CONFIG (ទទេ)
--==================================================
local DefaultConfig = {}

--==================================================
-- FILE HELPERS
--==================================================
local function EnsureFolder()
    pcall(function()
        if not isfolder(CONFIG_FOLDER) then
            makefolder(CONFIG_FOLDER)
        end
    end)
end

local function FileExists(Path)
    local Exists = false
    pcall(function()
        Exists = isfile(Path)
    end)
    return Exists
end

--==================================================
-- LOAD CONFIG (ទទេ)
--==================================================
local function LoadConfig()
    EnsureFolder()
    print("[VOIDCXZ] Config Loaded (Empty)")
    return {}
end

--==================================================
-- SAVE CONFIG (ទទេ)
--==================================================
local function SaveConfig(Config)
    EnsureFolder()

    local DataToSave = {}

    local EncodeSuccess, EncodedData = pcall(function()
        return HttpService:JSONEncode(DataToSave)
    end)

    if not EncodeSuccess then
        warn("[VOIDCXZ] Failed to encode config")
        return false
    end

    local WriteSuccess = pcall(function()
        writefile(CONFIG_FILE, EncodedData)
    end)

    if WriteSuccess then
        print("[VOIDCXZ] Config Saved (Empty)")
        return true
    else
        warn("[VOIDCXZ] Failed to write config")
        return false
    end
end

--==================================================
-- APPLY CONFIG (ទទេ)
--==================================================
local function ApplyConfig(Config)
    -- គ្មាន Apply អ្វីទេ
end

--==================================================
-- INITIAL LOAD
--==================================================
local LoadedConfig = LoadConfig()
ApplyConfig(LoadedConfig)

--==================================================
-- EXPORT
--==================================================
_G.VOIDCXZ_ConfigSystem = {
    Folder = CONFIG_FOLDER,
    File = CONFIG_FILE,
    Default = DefaultConfig,

    Load = function()
        local Config = LoadConfig()
        ApplyConfig(Config)

        task.spawn(function()
            task.wait(0.5)

            -- ✅ Update Event Tab UI
            pcall(function()
                if _G.VOIDCXZ_RefreshEventUI then
                    _G.VOIDCXZ_RefreshEventUI()
                end
            end)

            -- ✅ Update Setting Tab UI
            pcall(function()
                if _G.VOIDCXZ_RefreshSettingUI then
                    _G.VOIDCXZ_RefreshSettingUI()
                end
            end)
        end)

        return Config
    end,

    Save = function()
        return SaveConfig({})
    end,

    Get = function()
        return {}
    end,

    Reset = function()
        ApplyConfig(DefaultConfig)
        return SaveConfig(DefaultConfig)
    end
}

print("✅ ConfigSystem Loaded (Empty — No AttackDrone/SafeSpeedMode)")
]]
__VOIDCXZ_SOURCE[[[Features/DontUseIt.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Don't Use It
-- ✅ WalkSpeed 800 + Fast Click + Egg Check (Poll)
-- ✅ BodyV + BodyG តែម្នាក់ឯង (គ្មាន Tween)
-- ✅ Speed 400/s | Fly Offset 80 | Position Y = 70
-- ✅ Egg Collect = True → Fly Loop P3 ↔ P1 (No Stop)
-- ✅ TIMEOUT = 3 ម៉ោង (10,800s)
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ProximityPromptService = game:GetService("ProximityPromptService")

local Player = Players.LocalPlayer

-- ==================================================
-- SETTINGS
-- ==================================================
local WALK_SPEED_VALUE = 800
local TELEPORT_SPEED = 400
local FLY_OFFSET = 80
local WAIT_BETWEEN_POS = 0.1
local CHECK_INTERVAL = 0.1
local ARRIVE_DISTANCE = 3
local TIMEOUT = 10800  -- ✅ 3 ម៉ោង

local BODY_VELOCITY_P = 5000
local BODY_GYRO_P = 50000
local BODY_GYRO_D = 2000

-- Positions (Y = 70)
local POSITION_1 = Vector3.new(663, 70, -369)
local POSITION_3 = Vector3.new(5974, 70, -368)

-- ==================================================
-- STATE
-- ==================================================
local Enabled = false

-- WalkSpeed
local WalkSpeedConnection = nil
local OriginalWalkSpeed = 16

-- Fast Click
local FastClickPromptConnection = nil
local FastClickHeartbeatConnection = nil
local FastClickCounter = 0

-- Egg Check
local EggCheckThread = nil
local DropHeldEgg = nil
local EggCollectTriggered = false

-- Teleport
local FlyConnection = nil
local BodyVelocity = nil
local BodyGyro = nil
local FlyLoopRunning = false
local FlySequence = 0
local CurrentFlyStep = 1

-- Forward Declarations
local StartFlyLoop
local StopFly

-- ==================================================
-- GET HUMANOID
-- ==================================================
local function GetHumanoid()
    local Char = Player.Character
    if not Char then return nil, nil end
    return Char:FindFirstChildOfClass("Humanoid"), Char:FindFirstChild("HumanoidRootPart")
end

-- ==================================================
-- 1. WALK SPEED 800
-- ==================================================
local function StartWalkSpeed()
    local Hum = GetHumanoid()
    if Hum then
        OriginalWalkSpeed = Hum.WalkSpeed
        Hum.WalkSpeed = WALK_SPEED_VALUE
    end

    if WalkSpeedConnection then WalkSpeedConnection:Disconnect() end
    WalkSpeedConnection = RunService.Heartbeat:Connect(function()
        if not Enabled then return end
        local H = GetHumanoid()
        if H then H.WalkSpeed = WALK_SPEED_VALUE end
    end)

    print("[Don't use it] WalkSpeed: ON (" .. WALK_SPEED_VALUE .. ")")
end

local function StopWalkSpeed()
    if WalkSpeedConnection then
        WalkSpeedConnection:Disconnect()
        WalkSpeedConnection = nil
    end
    local Hum = GetHumanoid()
    if Hum then Hum.WalkSpeed = OriginalWalkSpeed end
    print("[Don't use it] WalkSpeed: OFF")
end

-- ==================================================
-- 2. FAST CLICK
-- ==================================================
local function ApplyHoldDuration(prompt)
    if not prompt then return end
    pcall(function() prompt.HoldDuration = 0 end)
end

local function ScanAllPrompts()
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("ProximityPrompt") then ApplyHoldDuration(d) end
    end
    local PG = Player:FindFirstChild("PlayerGui")
    if PG then
        for _, d in ipairs(PG:GetDescendants()) do
            if d:IsA("ProximityPrompt") then ApplyHoldDuration(d) end
        end
    end
end

local function StartFastClick()
    ScanAllPrompts()

    if FastClickPromptConnection then FastClickPromptConnection:Disconnect() end
    FastClickPromptConnection = ProximityPromptService.PromptShown:Connect(function(prompt)
        if not Enabled then return end
        ApplyHoldDuration(prompt)
    end)

    if FastClickHeartbeatConnection then FastClickHeartbeatConnection:Disconnect() end
    FastClickCounter = 0
    FastClickHeartbeatConnection = RunService.Heartbeat:Connect(function()
        if not Enabled then return end
        FastClickCounter = FastClickCounter + 1
        if FastClickCounter >= 30 then
            FastClickCounter = 0
            ScanAllPrompts()
        end
    end)

    print("[Don't use it] Fast Click: ON")
end

local function StopFastClick()
    if FastClickPromptConnection then FastClickPromptConnection:Disconnect() FastClickPromptConnection = nil end
    if FastClickHeartbeatConnection then FastClickHeartbeatConnection:Disconnect() FastClickHeartbeatConnection = nil end
    print("[Don't use it] Fast Click: OFF")
end

-- ==================================================
-- 3. EGG CHECK (POLL)
-- ==================================================
local function GetDropHeldEgg()
    local PG = Player:FindFirstChild("PlayerGui")
    if not PG then return nil end
    return PG:FindFirstChild("DropHeldEgg")
end

local function StartEggCheckThread()
    if EggCheckThread then
        pcall(function() task.cancel(EggCheckThread) end)
        EggCheckThread = nil
    end

    EggCheckThread = task.spawn(function()
        while Enabled do
            task.wait(CHECK_INTERVAL)

            if not DropHeldEgg or not DropHeldEgg.Parent then
                DropHeldEgg = GetDropHeldEgg()
            end

            if DropHeldEgg then
                local IsCollected = DropHeldEgg.Enabled == true

                if IsCollected and not EggCollectTriggered then
                    EggCollectTriggered = true
                    print("[Don't use it] ✅ Egg Collect = TRUE → Start Fly Loop")
                    if StartFlyLoop then StartFlyLoop() end
                elseif not IsCollected and EggCollectTriggered then
                    EggCollectTriggered = false
                    print("[Don't use it] ❌ Egg Collect = FALSE → Stop Fly Loop")
                    if StopFly then StopFly() end
                end
            end
        end
    end)

    print("[Don't use it] Egg Check Thread: STARTED")
end

local function StopEggCheckThread()
    if EggCheckThread then
        pcall(function() task.cancel(EggCheckThread) end)
        EggCheckThread = nil
    end
    print("[Don't use it] Egg Check Thread: STOPPED")
end

-- ==================================================
-- 4. CLEANUP MOVERS
-- ==================================================
local function CleanupMovers(KeepPlatformStand)
    if FlyConnection then
        FlyConnection:Disconnect()
        FlyConnection = nil
    end
    if BodyVelocity then
        pcall(function()
            BodyVelocity.Velocity = Vector3.zero
            BodyVelocity.MaxForce = Vector3.zero
        end)
        BodyVelocity:Destroy()
        BodyVelocity = nil
    end
    if BodyGyro then
        pcall(function() BodyGyro.MaxTorque = Vector3.zero end)
        BodyGyro:Destroy()
        BodyGyro = nil
    end

    local Hum, Root = GetHumanoid()
    if Root then
        for _, c in ipairs(Root:GetChildren()) do
            if c.Name == "VoidcxzBV" or c.Name == "VoidcxzBG" then
                pcall(function() c:Destroy() end)
            end
        end
    end
    if Hum and not KeepPlatformStand then
        pcall(function()
            Hum.PlatformStand = false
            Hum.Sit = false
        end)
    end
    if Root then
        pcall(function()
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

-- ==================================================
-- 5. BODYV + BODYG FLY TP
-- ==================================================
local function FlyTP(Destination, Callback)
    FlySequence = FlySequence + 1
    local Seq = FlySequence

    CleanupMovers()

    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local FlyPos = Vector3.new(Destination.X, Destination.Y + FLY_OFFSET, Destination.Z)
    local TargetCFrame = CFrame.new(FlyPos)

    Hum.PlatformStand = true

    BodyVelocity = Instance.new("BodyVelocity")
    BodyVelocity.Name = "VoidcxzBV"
    BodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    BodyVelocity.P = BODY_VELOCITY_P
    BodyVelocity.Velocity = Vector3.zero
    BodyVelocity.Parent = Root

    BodyGyro = Instance.new("BodyGyro")
    BodyGyro.Name = "VoidcxzBG"
    BodyGyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
    BodyGyro.P = BODY_GYRO_P
    BodyGyro.D = BODY_GYRO_D
    BodyGyro.CFrame = Root.CFrame
    BodyGyro.Parent = Root

    local StartTime = tick()

    FlyConnection = RunService.Heartbeat:Connect(function()
        if Seq ~= FlySequence then
            if FlyConnection then FlyConnection:Disconnect() FlyConnection = nil end
            return
        end
        if not Enabled then CleanupMovers() return end

        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 or Hum2.Health <= 0 then CleanupMovers() return end
        if not BodyVelocity or not BodyGyro then CleanupMovers() return end

        local CurrentPos = Root2.Position
        local Dir = FlyPos - CurrentPos
        local HorizDist = Vector3.new(Dir.X, 0, Dir.Z).Magnitude
        local VertDist = math.abs(Dir.Y)
        local TotalDist = Dir.Magnitude

        if HorizDist <= ARRIVE_DISTANCE and VertDist <= 2 then
            if BodyVelocity then
                BodyVelocity.Velocity = Vector3.zero
                BodyVelocity.MaxForce = Vector3.zero
            end
            if BodyGyro then BodyGyro.MaxTorque = Vector3.zero end
            if FlyConnection then FlyConnection:Disconnect() FlyConnection = nil end

            task.spawn(function()
                task.wait(0.05)
                CleanupMovers(true)
                Root2.CFrame = TargetCFrame
                Root2.AssemblyLinearVelocity = Vector3.zero
                Root2.AssemblyAngularVelocity = Vector3.zero
                if Callback then Callback() end
            end)
            return
        end

        if tick() - StartTime > TIMEOUT then
            CleanupMovers()
            if Callback then Callback() end
            return
        end

        if TotalDist > 1 then
            BodyVelocity.Velocity = Dir.Unit * TELEPORT_SPEED
        else
            BodyVelocity.Velocity = Vector3.zero
        end

        BodyGyro.CFrame = CFrame.new(CurrentPos, CurrentPos + Vector3.new(Dir.X, 0, Dir.Z))
    end)
end

-- ==================================================
-- 6. FLY LOOP (P3 ↔ P1 — No Stop)
-- ==================================================
local function FlyLoopStep()
    if not Enabled or not FlyLoopRunning then return end

    if CurrentFlyStep == 1 then
        print("[Don't use it] Fly → Position 3")
        FlyTP(POSITION_3, function()
            if not Enabled or not FlyLoopRunning then return end
            task.wait(WAIT_BETWEEN_POS)
            CurrentFlyStep = 2
            FlyLoopStep()
        end)
    else
        print("[Don't use it] Fly → Position 1")
        FlyTP(POSITION_1, function()
            if not Enabled or not FlyLoopRunning then return end
            task.wait(WAIT_BETWEEN_POS)
            CurrentFlyStep = 1
            FlyLoopStep()
        end)
    end
end

StartFlyLoop = function()
    if FlyLoopRunning then return end
    FlyLoopRunning = true
    CurrentFlyStep = 1

    print("[Don't use it] ✅ Fly Loop STARTED (P3 ↔ P1 — No Stop)")
    FlyLoopStep()
end

StopFly = function()
    FlyLoopRunning = false
    FlySequence = FlySequence + 1
    CleanupMovers()
    print("[Don't use it] Fly Loop: STOPPED")
end

-- ==================================================
-- ENABLE / DISABLE
-- ==================================================
local function Enable()
    if Enabled then return end
    Enabled = true
    EggCollectTriggered = false
    CurrentFlyStep = 1

    StartWalkSpeed()
    StartFastClick()
    StartEggCheckThread()

    print("[Don't use it] =========================")
    print("[Don't use it] COMBO: ON")
    print("[Don't use it] BodyV + BodyG | Speed 400/s | Offset 80")
    print("[Don't use it] =========================")
end

local function Disable()
    if not Enabled then return end
    Enabled = false
    EggCollectTriggered = false

    StopWalkSpeed()
    StopFastClick()
    StopEggCheckThread()
    StopFly()

    DropHeldEgg = nil

    print("[Don't use it] COMBO: OFF")
end

local function Toggle()
    if Enabled then Disable() else Enable() end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_DontUseIt = {
    Enable = Enable,
    Disable = Disable,
    Toggle = Toggle,
    IsEnabled = function() return Enabled end,
    POSITION_1 = POSITION_1,
    POSITION_3 = POSITION_3,
    TELEPORT_SPEED = TELEPORT_SPEED,
    FLY_OFFSET = FLY_OFFSET,
}

-- ==================================================
-- REGISTER WITH CHARACTER SYSTEM
-- ==================================================
if _G.VOIDCXZ_CharacterSystem then
    _G.VOIDCXZ_CharacterSystem:RegisterFeature({
        Name = "DontUseIt",
        Enable = Enable,
        Disable = Disable,
        IsEnabled = function() return Enabled end,
        OnCharacterAdded = function(Char, Hum, Root)
            if Enabled then
                task.wait(1)
                StartWalkSpeed()
                StartFastClick()
                StartEggCheckThread()
            end
        end
    })
end

print("✅ DontUseIt Feature Loaded (BodyV + BodyG | Speed 400/s | Offset 80)")
]]
__VOIDCXZ_SOURCE[[[Features/DropEgg.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | For Event Drop Egg
