        if H then H.WalkSpeed = WALK_SPEED_VALUE end
    end)

    print("[For Event Drop Egg] WalkSpeed: ON (" .. WALK_SPEED_VALUE .. ")")
end

local function StopWalkSpeed()
    if WalkSpeedConnection then
        WalkSpeedConnection:Disconnect()
        WalkSpeedConnection = nil
    end
    local Hum = GetHumanoid()
    if Hum then Hum.WalkSpeed = OriginalWalkSpeed end
    print("[For Event Drop Egg] WalkSpeed: OFF")
end

-- ==================================================
-- 2. FAST CLICK
-- ==================================================
local function ApplyHoldDuration(prompt)
    if not prompt then return end
    pcall(function() prompt.HoldDuration = 0 end)
end

local function ScanAllPrompts()
    for _, d in ipairs(workspace:GetDescendants()) do
        if d:IsA("ProximityPrompt") then ApplyHoldDuration(d) end
    end
    local PG = Player:FindFirstChild("PlayerGui")
    if PG then
        for _, d in ipairs(PG:GetDescendants()) do
            if d:IsA("ProximityPrompt") then ApplyHoldDuration(d) end
        end
    end
end

local function StartFastClick()
    ScanAllPrompts()

    if FastClickPromptConnection then FastClickPromptConnection:Disconnect() end
    FastClickPromptConnection = ProximityPromptService.PromptShown:Connect(function(prompt)
        if not Enabled then return end
        ApplyHoldDuration(prompt)
    end)

    if FastClickHeartbeatConnection then FastClickHeartbeatConnection:Disconnect() end
    FastClickCounter = 0
    FastClickHeartbeatConnection = RunService.Heartbeat:Connect(function()
        if not Enabled then return end
        FastClickCounter = FastClickCounter + 1
        if FastClickCounter >= 30 then
            FastClickCounter = 0
            ScanAllPrompts()
        end
    end)

    print("[For Event Drop Egg] Fast Click: ON")
end

local function StopFastClick()
    if FastClickPromptConnection then FastClickPromptConnection:Disconnect() FastClickPromptConnection = nil end
    if FastClickHeartbeatConnection then FastClickHeartbeatConnection:Disconnect() FastClickHeartbeatConnection = nil end
    print("[For Event Drop Egg] Fast Click: OFF")
end

-- ==================================================
-- 3. EGG CHECK (POLL)
-- ==================================================
local function GetDropHeldEgg()
    local PG = Player:FindFirstChild("PlayerGui")
    if not PG then return nil end
    return PG:FindFirstChild("DropHeldEgg")
end

local function StartEggCheckThread()
    if EggCheckThread then
        pcall(function() task.cancel(EggCheckThread) end)
        EggCheckThread = nil
    end

    EggCheckThread = task.spawn(function()
        while Enabled do
            task.wait(CHECK_INTERVAL)

            if not DropHeldEgg or not DropHeldEgg.Parent then
                DropHeldEgg = GetDropHeldEgg()
            end

            if DropHeldEgg then
                local IsCollected = DropHeldEgg.Enabled == true

                if IsCollected and not EggCollectTriggered then
                    EggCollectTriggered = true
                    print("[For Event Drop Egg] ✅ Egg Collect = TRUE → Start Fly Loop")
                    if StartFlyLoop then StartFlyLoop() end
                elseif not IsCollected and EggCollectTriggered then
                    EggCollectTriggered = false
                    print("[For Event Drop Egg] ❌ Egg Collect = FALSE → Stop Fly Loop")
                    if StopFly then StopFly() end
                end
            end
        end
    end)

    print("[For Event Drop Egg] Egg Check Thread: STARTED")
end

local function StopEggCheckThread()
    if EggCheckThread then
        pcall(function() task.cancel(EggCheckThread) end)
        EggCheckThread = nil
    end
    print("[For Event Drop Egg] Egg Check Thread: STOPPED")
end

-- ==================================================
-- 4. CLEANUP MOVERS
-- ==================================================
local function CleanupMovers(KeepPlatformStand)
    if FlyConnection then
        FlyConnection:Disconnect()
        FlyConnection = nil
    end
    if BodyVelocity then
        pcall(function()
            BodyVelocity.Velocity = Vector3.zero
            BodyVelocity.MaxForce = Vector3.zero
        end)
        BodyVelocity:Destroy()
        BodyVelocity = nil
    end
    if BodyGyro then
        pcall(function() BodyGyro.MaxTorque = Vector3.zero end)
        BodyGyro:Destroy()
        BodyGyro = nil
    end

    local Hum, Root = GetHumanoid()
    if Root then
        for _, c in ipairs(Root:GetChildren()) do
            if c.Name == "VoidcxzBV" or c.Name == "VoidcxzBG" then
                pcall(function() c:Destroy() end)
            end
        end
    end
    if Hum and not KeepPlatformStand then
        pcall(function()
            Hum.PlatformStand = false
            Hum.Sit = false
        end)
    end
    if Root then
        pcall(function()
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

-- ==================================================
-- 5. BODYV + BODYG FLY TP
-- ==================================================
local function FlyTP(Destination, Callback)
    FlySequence = FlySequence + 1
    local Seq = FlySequence

    CleanupMovers()

    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local FlyPos = Vector3.new(Destination.X, Destination.Y + FLY_OFFSET, Destination.Z)
    local TargetCFrame = CFrame.new(FlyPos)

    Hum.PlatformStand = true

    BodyVelocity = Instance.new("BodyVelocity")
    BodyVelocity.Name = "VoidcxzBV"
    BodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
    BodyVelocity.P = BODY_VELOCITY_P
    BodyVelocity.Velocity = Vector3.zero
    BodyVelocity.Parent = Root

    BodyGyro = Instance.new("BodyGyro")
    BodyGyro.Name = "VoidcxzBG"
    BodyGyro.MaxTorque = Vector3.new(math.huge, math.huge, math.huge)
    BodyGyro.P = BODY_GYRO_P
    BodyGyro.D = BODY_GYRO_D
    BodyGyro.CFrame = Root.CFrame
    BodyGyro.Parent = Root

    local StartTime = tick()

    FlyConnection = RunService.Heartbeat:Connect(function()
        if Seq ~= FlySequence then
            if FlyConnection then FlyConnection:Disconnect() FlyConnection = nil end
            return
        end
        if not Enabled then CleanupMovers() return end

        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 or Hum2.Health <= 0 then CleanupMovers() return end
        if not BodyVelocity or not BodyGyro then CleanupMovers() return end

        local CurrentPos = Root2.Position
        local Dir = FlyPos - CurrentPos
        local HorizDist = Vector3.new(Dir.X, 0, Dir.Z).Magnitude
        local VertDist = math.abs(Dir.Y)
        local TotalDist = Dir.Magnitude

        if HorizDist <= ARRIVE_DISTANCE and VertDist <= 2 then
            if BodyVelocity then
                BodyVelocity.Velocity = Vector3.zero
                BodyVelocity.MaxForce = Vector3.zero
            end
            if BodyGyro then BodyGyro.MaxTorque = Vector3.zero end
            if FlyConnection then FlyConnection:Disconnect() FlyConnection = nil end

            task.spawn(function()
                task.wait(0.05)
                CleanupMovers(true)
                Root2.CFrame = TargetCFrame
                Root2.AssemblyLinearVelocity = Vector3.zero
                Root2.AssemblyAngularVelocity = Vector3.zero
                if Callback then Callback() end
            end)
            return
        end

        if tick() - StartTime > TIMEOUT then
            CleanupMovers()
            if Callback then Callback() end
            return
        end

        if TotalDist > 1 then
            BodyVelocity.Velocity = Dir.Unit * TELEPORT_SPEED
        else
            BodyVelocity.Velocity = Vector3.zero
        end

        BodyGyro.CFrame = CFrame.new(CurrentPos, CurrentPos + Vector3.new(Dir.X, 0, Dir.Z))
    end)
end

-- ==================================================
-- 6. FLY LOOP (P3 ↔ P1 — No Stop)
-- ==================================================
local function FlyLoopStep()
    if not Enabled or not FlyLoopRunning then return end

    if CurrentFlyStep == 1 then
        print("[For Event Drop Egg] Fly → Position 3")
        FlyTP(POSITION_3, function()
            if not Enabled or not FlyLoopRunning then return end
            task.wait(WAIT_BETWEEN_POS)
            CurrentFlyStep = 2
            FlyLoopStep()
        end)
    else
        print("[For Event Drop Egg] Fly → Position 1")
        FlyTP(POSITION_1, function()
            if not Enabled or not FlyLoopRunning then return end
            task.wait(WAIT_BETWEEN_POS)
            CurrentFlyStep = 1
            FlyLoopStep()
        end)
    end
end

StartFlyLoop = function()
    if FlyLoopRunning then return end
    FlyLoopRunning = true
    CurrentFlyStep = 1

    print("[For Event Drop Egg] ✅ Fly Loop STARTED (P3 ↔ P1 — No Stop)")
    FlyLoopStep()
end

StopFly = function()
    FlyLoopRunning = false
    FlySequence = FlySequence + 1
    CleanupMovers()
    print("[For Event Drop Egg] Fly Loop: STOPPED")
end

-- ==================================================
-- ENABLE / DISABLE
-- ==================================================
local function Enable()
    if Enabled then return end
    Enabled = true
    EggCollectTriggered = false
    CurrentFlyStep = 1

    StartWalkSpeed()
    StartFastClick()
    StartEggCheckThread()

    print("[For Event Drop Egg] =========================")
    print("[For Event Drop Egg] COMBO: ON")
    print("[For Event Drop Egg] BodyV + BodyG | Speed 400/s | Offset 80")
    print("[For Event Drop Egg] =========================")
end

local function Disable()
    if not Enabled then return end
    Enabled = false
    EggCollectTriggered = false

    StopWalkSpeed()
    StopFastClick()
    StopEggCheckThread()
    StopFly()

    DropHeldEgg = nil

    print("[For Event Drop Egg] COMBO: OFF")
end

local function Toggle()
    if Enabled then Disable() else Enable() end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_DropEgg = {
    Enable = Enable,
    Disable = Disable,
    Toggle = Toggle,
    IsEnabled = function() return Enabled end,
    POSITION_1 = POSITION_1,
    POSITION_3 = POSITION_3,
    TELEPORT_SPEED = TELEPORT_SPEED,
    FLY_OFFSET = FLY_OFFSET,
}

-- ==================================================
-- REGISTER WITH CHARACTER SYSTEM
-- ==================================================
if _G.VOIDCXZ_CharacterSystem then
    _G.VOIDCXZ_CharacterSystem:RegisterFeature({
        Name = "DropEgg",
        Enable = Enable,
        Disable = Disable,
        IsEnabled = function() return Enabled end,
        OnCharacterAdded = function(Char, Hum, Root)
            if Enabled then
                task.wait(1)
                StartWalkSpeed()
                StartFastClick()
                StartEggCheckThread()
            end
        end
    })
end

print("✅ DropEgg Feature Loaded (For Event Drop Egg)")
]]
__VOIDCXZ_SOURCE[[[Features/EggCheckPremium.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Egg Check Premium
-- ជ្រើសរើស Egg តាម Rarity (Divine > Eternal > Secret) និង $/s
-- ✅ Register ជាមួយ CharacterSystem
-- ==================================================

local Players = game:GetService("Players")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Player = Players.LocalPlayer

-- ==================================================
-- STATE
-- ==================================================
local SelectedRarities = {}

-- ==================================================
-- MESHID MAP
-- ==================================================
local MeshIdMap = {}
local MeshIdMapBuilt = false

local function BuildMeshIdMap()
    if MeshIdMapBuilt then return end
    
    local Assets = ReplicatedStorage:FindFirstChild("Data")
    if not Assets then return end
    Assets = Assets:FindFirstChild("Assets")
    if not Assets then return end
    local Configs = Assets:FindFirstChild("Configs")
    local EggModels = ReplicatedStorage:FindFirstChild("Assets")
    if EggModels then EggModels = EggModels:FindFirstChild("Models") end
    if EggModels then EggModels = EggModels:FindFirstChild("Eggs") end
    if not Configs or not EggModels then return end

    for _, Config in ipairs(Configs:GetChildren()) do
        local Success, Module = pcall(function() return require(Config) end)
        if Success and Module and Module.Egg then
            local ModelName = Module.Egg.ModelName or Config.Name
            local Template = EggModels:FindFirstChild(ModelName)
            if Template then
                for _, Desc in ipairs(Template:GetDescendants()) do
                    if Desc:IsA("MeshPart") and Desc.MeshId ~= "" then
                        MeshIdMap[Desc.MeshId] = Config.Name
                    end
                    if Desc:IsA("SpecialMesh") and Desc.MeshId ~= "" then
                        MeshIdMap[Desc.MeshId] = Config.Name
                    end
                end
            end
        end
    end
    
    MeshIdMapBuilt = true
    print("[EggCheckPremium] MeshId Map Built: " .. tostring(#Configs:GetChildren()) .. " Configs")
end

-- ==================================================
-- GET PET DATA
-- ==================================================
local function GetPetData(AssetCategory)
    local Assets = ReplicatedStorage:FindFirstChild("Data")
    if not Assets then return nil end
    Assets = Assets:FindFirstChild("Assets")
    if not Assets then return nil end
    local Configs = Assets:FindFirstChild("Configs")
    if not Configs then return nil end

    local Config = Configs:FindFirstChild(AssetCategory)
    if not Config then return nil end

    local Success, Module = pcall(function() return require(Config) end)
    if not Success or not Module then return nil end

    return {
        Rarity = Module.Rarity and (Module.Rarity._id or Module.Rarity.RarityId) or nil,
        EarningRate = Module.EarningRate or 0,
        DisplayName = Module.DisplayName or AssetCategory
    }
end

-- ==================================================
-- FIND ASSET CATEGORY
-- ==================================================
local function FindAssetCategory(EggModel)
    if not MeshIdMapBuilt then BuildMeshIdMap() end
    
    for _, Desc in ipairs(EggModel:GetDescendants()) do
        if Desc:IsA("MeshPart") and Desc.MeshId ~= "" then
            local Cat = MeshIdMap[Desc.MeshId]
            if Cat then return Cat end
        end
        if Desc:IsA("SpecialMesh") and Desc.MeshId ~= "" then
            local Cat = MeshIdMap[Desc.MeshId]
            if Cat then return Cat end
        end
    end
    return nil
end

-- ==================================================
-- SORT EGG (Divine > Eternal > Secret > $/s)
-- ==================================================
local RARITY_PRIORITY = {
    Divine = 1,
    Eternal = 2,
    Secret = 3
}

local function SortEggs(EggList)
    table.sort(EggList, function(a, b)
        local Pa = RARITY_PRIORITY[a.Rarity] or 999
        local Pb = RARITY_PRIORITY[b.Rarity] or 999
        if Pa ~= Pb then return Pa < Pb end
        return a.EarningRate > b.EarningRate
    end)
end

-- ==================================================
-- FIND BEST EGG
-- ==================================================
local function FindBestEgg()
    local Container = workspace:FindFirstChild("AreaEggSlotsClient")
    if not Container then return nil end

    local EggList = {}

    for _, Slot in ipairs(Container:GetChildren()) do
        if Slot:IsA("Model") then
            local Category = FindAssetCategory(Slot)
            if Category then
                local Data = GetPetData(Category)
                if Data and SelectedRarities[Data.Rarity] then
                    table.insert(EggList, {
                        Slot = Slot,
                        Uid = Slot.Name,
                        Rarity = Data.Rarity,
                        EarningRate = Data.EarningRate,
                        DisplayName = Data.DisplayName
                    })
                end
            end
        end
    end

    if #EggList == 0 then return nil end
    SortEggs(EggList)
    return EggList[1]
end

-- ==================================================
-- FIND ALL EGGS
-- ==================================================
local function FindAllEggs()
    local Container = workspace:FindFirstChild("AreaEggSlotsClient")
    if not Container then return {} end

    local EggList = {}

    for _, Slot in ipairs(Container:GetChildren()) do
        if Slot:IsA("Model") then
            local Category = FindAssetCategory(Slot)
            if Category then
                local Data = GetPetData(Category)
                if Data and SelectedRarities[Data.Rarity] then
                    table.insert(EggList, {
                        Slot = Slot,
                        Uid = Slot.Name,
                        Rarity = Data.Rarity,
                        EarningRate = Data.EarningRate,
                        DisplayName = Data.DisplayName
                    })
                end
            end
        end
    end

    SortEggs(EggList)
    return EggList
end

-- ==================================================
-- CHECK EGG BY RARITY
-- ==================================================
local function GetEggsByRarity(Rarity)
    local AllEggs = FindAllEggs()
    local Filtered = {}
    
    for _, Egg in ipairs(AllEggs) do
        if Egg.Rarity == Rarity then
            table.insert(Filtered, Egg)
        end
    end
    
    return Filtered
end

-- ==================================================
-- SET RARITIES
-- ==================================================
local function SetRarities(List)
    SelectedRarities = {}
    for _, r in ipairs(List) do
        SelectedRarities[r] = true
    end
    print("[EggCheckPremium] Rarities: " .. table.concat(List, ", "))
end

local function GetRarities()
    local List = {}
    for r, _ in pairs(SelectedRarities) do
        table.insert(List, r)
    end
    return List
end

-- ==================================================
-- BUILD MESHID MAP ON LOAD
-- ==================================================
task.spawn(function()
    task.wait(1)
    BuildMeshIdMap()
end)

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_EggCheckPremium = {
    SetRarities = SetRarities,
    GetRarities = GetRarities,
    FindBestEgg = FindBestEgg,
    FindAllEggs = FindAllEggs,
    GetEggsByRarity = GetEggsByRarity,
    SortEggs = SortEggs,
    GetPetData = GetPetData,
    FindAssetCategory = FindAssetCategory,
    BuildMeshIdMap = BuildMeshIdMap,
    RARITY_PRIORITY = RARITY_PRIORITY
}

print("✅ EggCheckPremium Feature Loaded (Register)")
]]
__VOIDCXZ_SOURCE[[[Features/FarmingManager.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Farming Manager (v5 FULL)
-- ✅ Divine Priority
-- ✅ Filter Character + Player + First Egg
-- ✅ Prevent Loop Reset (LastTargetUid)
-- ✅ Character Respawn → Restart
-- ✅ WalkSpeed ផ្ទាល់
-- ✅ Distance < 5 → Jump Out AFK
-- ✅ Check Egg Alive
-- ✅ Call UID ថ្មី ពេល Complete
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Workspace = game:GetService("Workspace")

local Player = Players.LocalPlayer

-- ==================================================
-- AREA EGG CYCLE
-- ==================================================
local AreaEggCycle = nil
pcall(function()
    AreaEggCycle = require(ReplicatedStorage.Shared.Util.AreaEggCycle)
end)

-- ==================================================
-- SETTINGS
-- ==================================================
local NIGHT_CHECK_INTERVAL = 0.03
local DAY_CHECK_INTERVAL = 0.05
local SAFE_ZONE = Vector3.new(533, 70, -366)
local SAFE_ZONE_DIST = 5
local SAFE_WAIT_AFTER_REACH = 1
local WALK_TIMEOUT = 30
local LOOP_WAIT_AFTER_AFK = 2
local JUMP_OUT_DISTANCE = 5

-- ==================================================
-- CACHE SYSTEM
-- ==================================================
local Cache = {
    MeshIdMap = {},
    MeshIdMapBuilt = false,
    PetData = {},
    UidCategory = {},
}

-- ==================================================
-- RARITY PRIORITY
-- ==================================================
local RARITY_PRIORITY = {
    Divine = 1,
    Eternal = 2,
    Secret = 3,
    Mythic = 3,
    Legendary = 4,
    Epic = 5,
    Rare = 5,
    Uncommon = 5,
    Common = 5
}

-- ==================================================
-- SELECTED RARITIES (Default: Top1-Top5)
-- ==================================================
local SelectedRarities = {
    Divine = true, Eternal = true, Secret = true,
    Mythic = true, Legendary = true,
    Epic = false, Rare = false, Uncommon = false, Common = false
}

-- ==================================================
-- FILTER FUNCTIONS
-- ==================================================
local function IsPlayerCharacter(Obj)
    if not Obj then return false end
    
    if Obj:FindFirstChildOfClass("Humanoid") then return true end
    if Obj:FindFirstChild("HumanoidRootPart") then return true end
    
    for _, P in ipairs(Players:GetPlayers()) do
        if P.Name == Obj.Name or P.DisplayName == Obj.Name then
            return true
        end
    end
    
    for _, P in ipairs(Players:GetPlayers()) do
        if P.Character == Obj then return true end
    end
    
    return false
end

local function IsValidEgg(Obj)
    if not Obj then return false end
    if not Obj:IsA("Model") then return false end
    
    if string.find(Obj.Name, "FirstAreaEgg") then return false end
    if IsPlayerCharacter(Obj) then return false end
    
    for _, P in ipairs(Players:GetPlayers()) do
        if P.Name == Obj.Name or P.DisplayName == Obj.Name then
            return false
        end
    end
    
    return true
end

local function CheckEggAlive(Uid)
    if not Uid then return false end
    
    local Container = workspace:FindFirstChild("AreaEggSlotsClient")
    local InContainer = Container and Container:FindFirstChild(Uid)
    local InWorkspace = workspace:FindFirstChild(Uid)
    
    local Egg = InContainer or InWorkspace
    if not Egg then return false end
    if not Egg:FindFirstChildWhichIsA("BasePart") then return false end
    
    return true
end

-- ==================================================
-- BUILD MESHID MAP
-- ==================================================
local function BuildMeshIdMap()
    if Cache.MeshIdMapBuilt then return end

    local Assets = ReplicatedStorage:FindFirstChild("Data")
    if not Assets then return end
    Assets = Assets:FindFirstChild("Assets")
    if not Assets then return end
    local Configs = Assets:FindFirstChild("Configs")
    local EggModels = ReplicatedStorage:FindFirstChild("Assets")
    if EggModels then EggModels = EggModels:FindFirstChild("Models") end
    if EggModels then EggModels = EggModels:FindFirstChild("Eggs") end
    if not Configs or not EggModels then return end

    for _, Config in ipairs(Configs:GetChildren()) do
        local Success, Module = pcall(function() return require(Config) end)
        if Success and Module and Module.Egg then
            local ModelName = Module.Egg.ModelName or Config.Name
            local Template = EggModels:FindFirstChild(ModelName)
            if Template then
                for _, Desc in ipairs(Template:GetDescendants()) do
                    if Desc:IsA("MeshPart") and Desc.MeshId ~= "" then
                        Cache.MeshIdMap[Desc.MeshId] = Config.Name
                    end
                    if Desc:IsA("SpecialMesh") and Desc.MeshId ~= "" then
                        Cache.MeshIdMap[Desc.MeshId] = Config.Name
                    end
                end
            end
        end
    end

    Cache.MeshIdMapBuilt = true
    print("[FarmingManager] MeshId Map Built")
end

-- ==================================================
-- GET PET DATA
-- ==================================================
local function GetPetData(AssetCategory)
    if not AssetCategory then return nil end
    if Cache.PetData[AssetCategory] then return Cache.PetData[AssetCategory] end

    local Assets = ReplicatedStorage:FindFirstChild("Data")
    if not Assets then return nil end
    Assets = Assets:FindFirstChild("Assets")
    if not Assets then return nil end
    local Configs = Assets:FindFirstChild("Configs")
    if not Configs then return nil end

    local Config = Configs:FindFirstChild(AssetCategory)
    if not Config then return nil end

    local Success, Module = pcall(function() return require(Config) end)
    if not Success or not Module then return nil end

    local Data = {
        Rarity = Module.Rarity and (Module.Rarity._id or Module.Rarity.RarityId) or nil,
        EarningRate = Module.EarningRate or 0,
        DisplayName = Module.DisplayName or AssetCategory
    }

    Cache.PetData[AssetCategory] = Data
    return Data
end

-- ==================================================
-- FIND ASSET CATEGORY
-- ==================================================
local function FindAssetCategory(EggModel)
    if not EggModel then return nil end

    local Uid = EggModel.Name
    if Cache.UidCategory[Uid] then return Cache.UidCategory[Uid] end

    if not Cache.MeshIdMapBuilt then BuildMeshIdMap() end

    for _, Desc in ipairs(EggModel:GetDescendants()) do
        if Desc:IsA("MeshPart") and Desc.MeshId ~= "" then
            local Cat = Cache.MeshIdMap[Desc.MeshId]
            if Cat then Cache.UidCategory[Uid] = Cat return Cat end
        end
        if Desc:IsA("SpecialMesh") and Desc.MeshId ~= "" then
            local Cat = Cache.MeshIdMap[Desc.MeshId]
            if Cat then Cache.UidCategory[Uid] = Cat return Cat end
        end
    end

    return nil
end

-- ==================================================
-- SORT EGGS
-- ==================================================
local function SortEggs(EggList)
    table.sort(EggList, function(a, b)
        local Pa = RARITY_PRIORITY[a.Rarity] or 999
        local Pb = RARITY_PRIORITY[b.Rarity] or 999
        if Pa ~= Pb then return Pa < Pb end
        return a.EarningRate > b.EarningRate
    end)
end

-- ==================================================
-- FIND BEST EGG (Divine Priority)
-- ==================================================
local function FindBestEgg()
    local EggList = {}
    local DivineEgg = nil
    local DivineEarningRate = 0

    local Container = workspace:FindFirstChild("AreaEggSlotsClient")
    if Container then
        for _, Slot in ipairs(Container:GetChildren()) do
            if Slot:IsA("Model") then
                if not IsValidEgg(Slot) then continue end
                if not Slot.Parent then continue end
                if not Slot:FindFirstChildWhichIsA("BasePart") then continue end
                
                local Category = FindAssetCategory(Slot)
                if Category then
                    local Data = GetPetData(Category)
                    if Data and SelectedRarities[Data.Rarity] then
                        if Data.Rarity == "Divine" then
                            if Data.EarningRate > DivineEarningRate then
                                DivineEarningRate = Data.EarningRate
                                DivineEgg = {
                                    Slot = Slot, Uid = Slot.Name, Rarity = "Divine",
                                    EarningRate = Data.EarningRate, DisplayName = Data.DisplayName,
                                    Location = "spawn"
                                }
                            end
                        end
                        
                        table.insert(EggList, {
                            Slot = Slot, Uid = Slot.Name, Rarity = Data.Rarity,
                            EarningRate = Data.EarningRate, DisplayName = Data.DisplayName,
                            Location = "spawn"
                        })
                    end
                end
            end
        end
    end

    if DivineEgg then
        print("[FarmingManager] ✨ Divine Egg (Priority):", DivineEgg.DisplayName)
        return DivineEgg
    end

    if #EggList > 0 then SortEggs(EggList) return EggList[1] end

    -- Workspace Backup
    local WsDivineEgg = nil
    local WsDivineEarningRate = 0

    for _, Obj in ipairs(workspace:GetChildren()) do
        if Obj:IsA("Model") then
            if not IsValidEgg(Obj) then continue end
            if not Obj.Parent then continue end
            if not Obj:FindFirstChildWhichIsA("BasePart") then continue end
            
            local Category = FindAssetCategory(Obj)
            if Category then
                local Data = GetPetData(Category)
                if Data and SelectedRarities[Data.Rarity] then
                    if Data.Rarity == "Divine" then
                        if Data.EarningRate > WsDivineEarningRate then
                            WsDivineEarningRate = Data.EarningRate
                            WsDivineEgg = {
                                Slot = Obj, Uid = Obj.Name, Rarity = "Divine",
                                EarningRate = Data.EarningRate, DisplayName = Data.DisplayName,
                                Location = "workspace"
                            }
                        end
                    end
                    
                    table.insert(EggList, {
                        Slot = Obj, Uid = Obj.Name, Rarity = Data.Rarity,
                        EarningRate = Data.EarningRate, DisplayName = Data.DisplayName,
                        Location = "workspace"
                    })
                end
            end
        end
    end

    if WsDivineEgg then
        print("[FarmingManager] ✨ Divine Egg (Workspace):", WsDivineEgg.DisplayName)
        return WsDivineEgg
    end

    if #EggList == 0 then return nil end
    SortEggs(EggList)
    return EggList[1]
end

-- ==================================================
-- SET RARITIES
-- ==================================================
local function SetRarities(List)
    SelectedRarities = {}
    for _, r in ipairs(List) do
        SelectedRarities[r] = true
    end
    print("[FarmingManager] Rarities: " .. table.concat(List, ", "))
end

-- ==================================================
-- STATE
-- ==================================================
local FarmingEnabled = false
local CurrentState = "IDLE"
local CurrentPhase = "UNKNOWN"
local FarmingThread = nil
local AFKStarted = false
local PendingEggUid = nil
local WaitingForTeleport = false
local LastTargetUid = nil
local WalkConnection = nil

-- ==================================================
-- GET CHAR / ROOT / HUM
-- ==================================================
local function GetChar() return Player.Character end
local function GetRoot()
    local Char = GetChar()
    if not Char then return nil end
    return Char:FindFirstChild("HumanoidRootPart")
end
local function GetHum()
    local Char = GetChar()
    if not Char then return nil end
    return Char:FindFirstChildOfClass("Humanoid")
end

-- ==================================================
-- CLEANUP WALK
-- ==================================================
local function CleanupWalk()
    if WalkConnection then WalkConnection:Disconnect() WalkConnection = nil end

    local Hum = GetHum()
    local Root = GetRoot()
    if Hum then
        pcall(function() Hum:MoveTo(Root and Root.Position or Hum.Parent.HumanoidRootPart.Position) end)
    end
    if Root then
        pcall(function()
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

-- ==================================================
-- WALK TP (WalkSpeed ផ្ទាល់)
-- ==================================================
local function WalkTP(Destination, Callback)
    CleanupWalk()

    local Hum = GetHum()
    local Root = GetRoot()
    if not Hum or not Root then
        if Callback then Callback() end
        return
    end
    if Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local PlayerSpeed = Hum.WalkSpeed
    print(string.format("[FarmingManager] 🚶 Walk TP → %s | Speed: %.1f", tostring(Destination), PlayerSpeed))

    local StartTime = tick()
    local LastCheck = 0

    WalkConnection = RunService.Heartbeat:Connect(function()
        if not FarmingEnabled then CleanupWalk() return end

        local Hum2 = GetHum()
        local Root2 = GetRoot()
        if not Hum2 or not Root2 then CleanupWalk() return end
        if Hum2.Health <= 0 then CleanupWalk() return end

        Hum2:MoveTo(Destination)

        if tick() - LastCheck > 0.05 then
            LastCheck = tick()

            local Dist = (Root2.Position - Destination).Magnitude
            if Dist <= 3 then
                CleanupWalk()
                print(string.format("[FarmingManager] ✅ Walk TP Arrived | Dist: %.1f", Dist))
                if Callback then Callback() end
                return
            end

            if tick() - StartTime > WALK_TIMEOUT then
                CleanupWalk()
                print("[FarmingManager] Walk TP Timeout")
                if Callback then Callback() end
                return
            end
        end
    end)
end

-- ==================================================
-- GET PHASE
-- ==================================================
local function GetPhase()
    if AreaEggCycle then
        local Success, IsNight = pcall(function() return AreaEggCycle.IsNightPhase(Workspace:GetServerTimeNow()) end)
        if Success then return IsNight and "Night" or "Day" end
    end

    local Success, Text = pcall(function() return Player.PlayerGui.HUD.GameHUD.BottomRight.NightTimer.Value.Text end)
    if Success and Text then
        local M = tonumber(string.match(Text, "(%d+)m")) or 0
        local S = tonumber(string.match(Text, "(%d+)s")) or 0
        local Sec = M * 60 + S
        return Sec > 10 and "Day" or "Night"
    end

    return "UNKNOWN"
end

-- ==================================================
-- STOP ALL
-- ==================================================
local function StopAll()
    if _G.VOIDCXZ_AFKSystem and _G.VOIDCXZ_AFKSystem.IsEnabled() then
        local TreadmillPos = _G.VOIDCXZ_AFKSystem.GetMyTreadmillPos()
        if not TreadmillPos then
            local _, Treadmill = _G.VOIDCXZ_AFKSystem.FindMyPlotAndTreadmill()
            if Treadmill then TreadmillPos = Treadmill.Position end
        end
        if TreadmillPos then
            _G.VOIDCXZ_AFKSystem.JumpOutTreadmill(TreadmillPos, function()
                _G.VOIDCXZ_AFKSystem.Disable()
                AFKStarted = false
            end)
        else
            _G.VOIDCXZ_AFKSystem.Disable()
            AFKStarted = false
        end
    end

    if _G.VOIDCXZ_TeleportSystem and _G.VOIDCXZ_TeleportSystem.IsEnabled() then
        _G.VOIDCXZ_TeleportSystem.Disable()
    end

    CleanupWalk()
end

-- ==================================================
-- FLY TO SAFE ZONE
-- ==================================================
local function FlyToSafeZoneAndWait()
    local Root = GetRoot()
    if not Root then return false end

    local DistToSafe = (Root.Position - SAFE_ZONE).Magnitude
    if DistToSafe <= SAFE_ZONE_DIST then return true end

    WalkTP(SAFE_ZONE)

    local WaitTime = 0
    while FarmingEnabled and WaitTime < 15 do
        local Root2 = GetRoot()
        if Root2 then
            local Dist = (Root2.Position - SAFE_ZONE).Magnitude
            if Dist <= SAFE_ZONE_DIST then return true end
        end
        task.wait(0.05)
        WaitTime = WaitTime + 0.05
    end

    return false
end

-- ==================================================
-- START TELEPORT SYSTEM
-- ==================================================
local function StartTeleportSystem(EggUid)
    if not _G.VOIDCXZ_TeleportSystem then
        warn("[FarmingManager] TeleportSystem not loaded!")
        return false
    end

    print("[FarmingManager] Starting TeleportSystem | UID:", EggUid)

    WaitingForTeleport = true
    _G.VOIDCXZ_TeleportSystem.SetTargetId(EggUid)
    _G.VOIDCXZ_TeleportSystem.Enable()
    return true
end

-- ==================================================
-- ENABLE AFK
-- ==================================================
local function EnableAFK()
    if _G.VOIDCXZ_AFKSystem and not _G.VOIDCXZ_AFKSystem.IsEnabled() then
        _G.VOIDCXZ_AFKSystem.Enable()
        AFKStarted = true
        print("[FarmingManager] ✅ AFKSystem Enabled")
    end
end

-- ==================================================
-- ON TELEPORT COMPLETE
-- ==================================================
local function OnTeleportComplete()
    if not FarmingEnabled then return end
    if not WaitingForTeleport then return end

    WaitingForTeleport = false
    AFKStarted = false
    print("[FarmingManager] ✅ TeleportSystem Completed → Check New Egg")

    local BestEgg = FindBestEgg()

    if BestEgg then
        if not CheckEggAlive(BestEgg.Uid) then
            warn("[FarmingManager] ⚠️ Egg Target Gone → AFK")
            task.wait(1)
            EnableAFK()
            return
        end
        
        if BestEgg.Uid == LastTargetUid then
            warn("[FarmingManager] ⚠️ Same Target → Skip Loop")
            task.wait(1)
            EnableAFK()
            return
        end
        
        LastTargetUid = BestEgg.Uid
        print("[FarmingManager] New Egg Found:", BestEgg.DisplayName, "| Rarity:", BestEgg.Rarity)
        PendingEggUid = BestEgg.Uid

        task.spawn(function()
            local ReachedSafe = FlyToSafeZoneAndWait()
            if ReachedSafe and PendingEggUid then
                task.wait(SAFE_WAIT_AFTER_REACH)
                StartTeleportSystem(PendingEggUid)
                PendingEggUid = nil
            else
                EnableAFK()
            end
        end)
    else
        print("[FarmingManager] ❌ No Egg → Enable AFK")
        EnableAFK()
    end
end

-- ==================================================
-- MAIN LOOP
-- ==================================================
local function MainLoop()
    print("[FarmingManager] MainLoop Started")

    while FarmingEnabled do
        local Phase = GetPhase()
        CurrentPhase = Phase

        local BestEgg = FindBestEgg()

        if BestEgg then
            if CheckEggAlive(BestEgg.Uid) then
                print("[FarmingManager] ✅ Egg Found:", BestEgg.DisplayName, "| Rarity:", BestEgg.Rarity, "| $/s:", BestEgg.EarningRate)
                PendingEggUid = BestEgg.Uid
                LastTargetUid = BestEgg.Uid

                StopAll()
                task.wait(0.3)

                local ReachedSafe = FlyToSafeZoneAndWait()
                if ReachedSafe and PendingEggUid then
                    task.wait(SAFE_WAIT_AFTER_REACH)
                    StartTeleportSystem(PendingEggUid)
                    PendingEggUid = nil

                    while WaitingForTeleport and FarmingEnabled do
                        task.wait(0.2)
                    end
                else
                    print("[FarmingManager] ⚠️ Cannot reach Safe Zone → AFK")
                    EnableAFK()
                end
            else
                warn("[FarmingManager] ⚠️ Egg Target Gone → AFK")
                task.wait(1)
                EnableAFK()
            end
        else
            print("[FarmingManager] ❌ No Egg → Enable AFK")
            EnableAFK()
        end

        task.wait(LOOP_WAIT_AFTER_AFK)
    end

    print("[FarmingManager] MainLoop Stopped")
end

-- ==================================================
-- ENABLE / DISABLE
-- ==================================================
local function Enable()
    if FarmingEnabled then return end
    FarmingEnabled = true
    CurrentState = "CHECK_TIME"
    AFKStarted = false
    PendingEggUid = nil
    WaitingForTeleport = false
    LastTargetUid = nil

    if _G.VOIDCXZ_AFKSystem and _G.VOIDCXZ_AFKSystem.IsEnabled() then
        local MyTreadmillPos = _G.VOIDCXZ_AFKSystem.GetMyTreadmillPos()
        local Root = GetRoot()
        
        if MyTreadmillPos and Root then
            local Dist = (Root.Position - MyTreadmillPos).Magnitude
            
            if Dist < JUMP_OUT_DISTANCE then
                print(string.format("[FarmingManager] 🦘 Distance: %.1f (< %d) → Jump Out", Dist, JUMP_OUT_DISTANCE))
                
                _G.VOIDCXZ_AFKSystem.JumpOutTreadmill(MyTreadmillPos, function()
                    _G.VOIDCXZ_AFKSystem.Disable()
                    AFKStarted = false
                    print("[FarmingManager] ✅ Jumped Out")
                end)
                
                task.wait(1.5)
            else
                _G.VOIDCXZ_AFKSystem.Disable()
                task.wait(0.5)
            end
        else
            _G.VOIDCXZ_AFKSystem.Disable()
            task.wait(0.5)
        end
    end

    if FarmingThread then
        pcall(function() task.cancel(FarmingThread) end)
        FarmingThread = nil
    end
    
    task.wait(0.5)
    FarmingThread = task.spawn(function() MainLoop() end)

    print("[VOIDCXZ] FarmingManager: ON")
end

local function Disable()
    if not FarmingEnabled then return end
    FarmingEnabled = false

    if FarmingThread then
        pcall(function() task.cancel(FarmingThread) end)
        FarmingThread = nil
    end

    StopAll()

    AFKStarted = false
    PendingEggUid = nil
    WaitingForTeleport = false
    LastTargetUid = nil
    CurrentState = "IDLE"
    CurrentPhase = "UNKNOWN"
    print("[VOIDCXZ] FarmingManager: OFF")
end

local function Toggle()
    if FarmingEnabled then Disable() else Enable() end
end

-- ==================================================
-- CHARACTER RESPAWN
-- ==================================================
local function SetupDeathListener(Char)
    if not Char then return end
    local Hum = Char:FindFirstChildOfClass("Humanoid")
    if not Hum then return end
    
    Hum.Died:Connect(function()
        print("[FarmingManager] ☠️ Player Died")
        if FarmingEnabled then
            if _G.VOIDCXZ_TeleportSystem and _G.VOIDCXZ_TeleportSystem.IsEnabled() then
                _G.VOIDCXZ_TeleportSystem.Disable()
            end
            if _G.VOIDCXZ_AFKSystem and _G.VOIDCXZ_AFKSystem.IsEnabled() then
                _G.VOIDCXZ_AFKSystem.Disable()
            end
            CleanupWalk()
            WaitingForTeleport = false
        end
    end)
end

Player.CharacterAdded:Connect(function(Char)
    if not FarmingEnabled then return end
    print("[FarmingManager] 🔄 Character Respawned → Restart")
    task.wait(3)
    
    if FarmingThread then
        pcall(function() task.cancel(FarmingThread) end)
        FarmingThread = nil
    end
    
    WaitingForTeleport = false
    AFKStarted = false
    PendingEggUid = nil
    LastTargetUid = nil
    
    task.wait(2)
    FarmingThread = task.spawn(function() MainLoop() end)
    
    print("[FarmingManager] ✅ Farming Restarted")
    SetupDeathListener(Char)
end)

if Player.Character then SetupDeathListener(Player.Character) end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_FarmingManager = {
    Enable = Enable,
    Disable = Disable,
    Toggle = Toggle,
    IsEnabled = function() return FarmingEnabled end,
    SetRarities = SetRarities,
    GetState = function() return CurrentState end,
    GetPhase = function() return CurrentPhase end,
    FindBestEgg = FindBestEgg,
    CheckEggAlive = CheckEggAlive,

    GetEggData = function(Uid)
        if not Uid then return nil end
        local Container = workspace:FindFirstChild("AreaEggSlotsClient")
        local Slot = (Container and Container:FindFirstChild(Uid)) or workspace:FindFirstChild(Uid)
        if not Slot then return nil end
        local Category = FindAssetCategory(Slot)
        if not Category then return nil end
        return GetPetData(Category)
    end,

    JUMP_OUT_DISTANCE = JUMP_OUT_DISTANCE,
    OnTeleportComplete = OnTeleportComplete,
    WalkTP = WalkTP,
}

task.spawn(function()
    task.wait(1)
    BuildMeshIdMap()
    print("[FarmingManager] Cache Ready")
end)

task.spawn(function()
    while task.wait(30) do
        Cache.UidCategory = {}
        print("[FarmingManager] Uid Cache Cleared")
    end
end)

print("✅ FarmingManager Loaded (v5 FINAL)")
]]
__VOIDCXZ_SOURCE[[[Features/GodMode.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | God Mode
-- Humanoid Replace + Anti Death
-- ==================================================

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")

local Player = Players.LocalPlayer

-- ==================================================
-- VARIABLES
-- ==================================================
local GodModeEnabled = false
local GodModeConnection = nil
local GodMode = true

-- ==================================================
-- RUN HUMANOID REPLACE + ANTI DEATH
-- ==================================================
local function RunGodMode()
    local Character = Player.Character
    if not Character then return end

    local OldHumanoid = Character:FindFirstChildOfClass("Humanoid")
    if not OldHumanoid then
        warn("[VOIDCXZ] Humanoid not found")
        return
    end

    print("========================================")
    print("[VOIDCXZ] START HUMANOID REPLACE")
    print("========================================")

    -- SAVE JUMP PROPERTIES
    local SavedJumpProperties = {}

    local function SaveJumpProperty(Property)
        local Success, Value = pcall(function()
            return OldHumanoid[Property]
        end)
        if Success then
            SavedJumpProperties[Property] = Value
        end
    end

    SaveJumpProperty("JumpPower")
    SaveJumpProperty("JumpHeight")
    SaveJumpProperty("UseJumpPower")

    -- SAVE STATE MACHINE
    local SavedEvaluateStateMachine
    pcall(function()
        SavedEvaluateStateMachine = OldHumanoid.EvaluateStateMachine
    end)

    -- SAVE ALL HUMANOID STATE SETTINGS
    local SavedStates = {}
    local States = {
        Enum.HumanoidStateType.FallingDown,
        Enum.HumanoidStateType.Running,
        Enum.HumanoidStateType.RunningNoPhysics,
        Enum.HumanoidStateType.Climbing,
        Enum.HumanoidStateType.StrafingNoPhysics,
        Enum.HumanoidStateType.Ragdoll,
        Enum.HumanoidStateType.GettingUp,
        Enum.HumanoidStateType.Jumping,
        Enum.HumanoidStateType.Landed,
        Enum.HumanoidStateType.Flying,
        Enum.HumanoidStateType.Freefall,
        Enum.HumanoidStateType.Seated,
        Enum.HumanoidStateType.PlatformStanding,
        Enum.HumanoidStateType.Dead,
        Enum.HumanoidStateType.Swimming,
        Enum.HumanoidStateType.Physics,
    }

    for _, State in ipairs(States) do
        local Success, Enabled = pcall(function()
            return OldHumanoid:GetStateEnabled(State)
        end)
        if Success then
            SavedStates[State] = Enabled
        end
    end

    -- CLONE HUMANOID
    local NewHumanoid = OldHumanoid:Clone()
    if not NewHumanoid then
        warn("[VOIDCXZ] Failed to clone Humanoid")
        return
    end
    NewHumanoid.Name = OldHumanoid.Name

    -- MOVE HUMANOID CHILDREN
    for _, Child in ipairs(OldHumanoid:GetChildren()) do
        local ExistingCloneChild = NewHumanoid:FindFirstChild(Child.Name)
        if ExistingCloneChild then
            pcall(function()
                ExistingCloneChild:Destroy()
            end)
        end
        pcall(function()
            Child.Parent = NewHumanoid
        end)
    end

    -- REPLACEMENT ORDER
    OldHumanoid:Destroy()
    task.wait()
    NewHumanoid.Parent = Character
    task.wait()

    if not NewHumanoid.Parent then
        warn("[VOIDCXZ] New Humanoid was removed")
        return
    end

    print("[VOIDCXZ] New Humanoid:", NewHumanoid)

    -- RESTORE JUMP PROPERTIES
    pcall(function()
        NewHumanoid.UseJumpPower = SavedJumpProperties.UseJumpPower
    end)
    pcall(function()
        NewHumanoid.JumpPower = SavedJumpProperties.JumpPower
    end)
    pcall(function()
        NewHumanoid.JumpHeight = SavedJumpProperties.JumpHeight
    end)

    -- RESTORE EVALUATE STATE MACHINE
    pcall(function()
        if SavedEvaluateStateMachine ~= nil then
            NewHumanoid.EvaluateStateMachine = SavedEvaluateStateMachine
        end
    end)

    -- RESTORE HUMANOID STATE SETTINGS
    for State, Enabled in pairs(SavedStates) do
        pcall(function()
            NewHumanoid:SetStateEnabled(State, Enabled)
        end)
    end

    -- ENSURE ANIMATOR
    local Animator = NewHumanoid:FindFirstChildOfClass("Animator")
    if not Animator then
        Animator = Instance.new("Animator")
        Animator.Parent = NewHumanoid
    end
    print("[VOIDCXZ] Animator:", Animator)

    -- RESTART ANIMATE
    local Animate = Character:FindFirstChild("Animate")
    if Animate then
        print("[VOIDCXZ] Restarting Animate...")
        pcall(function()
            Animate.Disabled = true
        end)
        task.wait()
        pcall(function()
            Animate.Disabled = false
        end)
        print("[VOIDCXZ] Animate restarted")
    end

    task.wait(0.15)

    -- ANTI DEATH FUNCTIONS
    local function LockHealth()
        if GodMode and NewHumanoid and NewHumanoid.Parent then
            pcall(function()
                NewHumanoid.MaxHealth = math.huge
                NewHumanoid.Health = math.huge
            end)
        end
    end

    local function BlockDeathState()
        if not NewHumanoid or not NewHumanoid.Parent then return end
        pcall(function()
            NewHumanoid:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
        end)
        pcall(function()
            NewHumanoid.BreakJointsOnDeath = false
        end)
        pcall(function()
            NewHumanoid.RequiresNeck = false
        end)
    end

    local function BindAntiDeath(Humanoid)
        if not Humanoid then return end
        Humanoid.HealthChanged:Connect(function(Health)
            if GodMode and Humanoid and Humanoid.Parent then
                if Health < Humanoid.MaxHealth then
                    pcall(function()
                        Humanoid.Health = Humanoid.MaxHealth
                    end)
                end
            end
        end)
        Humanoid.Died:Connect(function()
            if GodMode and Humanoid and Humanoid.Parent then
                pcall(function()
                    Humanoid.Health = Humanoid.MaxHealth
                end)
            end
        end)
    end

    LockHealth()
    BlockDeathState()
    BindAntiDeath(NewHumanoid)

    -- CONTROL MODULE
    local function RefreshControls()
        local PlayerScripts = Player:FindFirstChild("PlayerScripts")
        if not PlayerScripts then return end
        local PlayerModule = PlayerScripts:FindFirstChild("PlayerModule")
        if not PlayerModule then return end
        local Success, Module = pcall(function()
            return require(PlayerModule)
        end)
        if not Success or not Module then return end
        local Controls
        pcall(function()
            Controls = Module:GetControls()
        end)
        if not Controls then return end
        pcall(function()
            Controls:OnCharacterAdded(Character)
        end)
        task.wait()
        pcall(function()
            Controls:UpdateActiveControlModuleEnabled()
        end)
    end

    RefreshControls()

    -- CAMERA
    pcall(function()
        local Camera = workspace.CurrentCamera
        if Camera then
            Camera.CameraSubject = NewHumanoid
        end
    end)

    -- FINAL STATE RESTORE
    task.wait(0.25)

    if not Character.Parent then return end

    local CurrentHumanoid = Character:FindFirstChildOfClass("Humanoid")
    if CurrentHumanoid ~= NewHumanoid then return end

    pcall(function()
        NewHumanoid.UseJumpPower = SavedJumpProperties.UseJumpPower
    end)
    pcall(function()
        NewHumanoid.JumpPower = SavedJumpProperties.JumpPower
    end)
    pcall(function()
        NewHumanoid.JumpHeight = SavedJumpProperties.JumpHeight
    end)
    pcall(function()
        if SavedEvaluateStateMachine ~= nil then
            NewHumanoid.EvaluateStateMachine = SavedEvaluateStateMachine
        end
    end)

    for State, Enabled in pairs(SavedStates) do
        pcall(function()
            NewHumanoid:SetStateEnabled(State, Enabled)
        end)
    end

    LockHealth()
    BlockDeathState()
    RefreshControls()

    pcall(function()
        local Camera = workspace.CurrentCamera
        if Camera then
            Camera.CameraSubject = NewHumanoid
        end
    end)

    -- FINAL ANIMATE RESTART
    local CurrentAnimate = Character:FindFirstChild("Animate")
    if CurrentAnimate then
        pcall(function()
            CurrentAnimate.Disabled = true
        end)
        task.wait()
        pcall(function()
            CurrentAnimate.Disabled = false
        end)
    end

    -- START GOD MODE LOOP
    if GodModeConnection then
        GodModeConnection:Disconnect()
        GodModeConnection = nil
    end

    GodModeConnection = RunService.Heartbeat:Connect(function()
        if not GodModeEnabled then return end

        local Char = Player.Character
        if not Char then return end

        local Hum = Char:FindFirstChildOfClass("Humanoid")
        if not Hum then return end

        pcall(function()
            if Hum.Health < Hum.MaxHealth then
                Hum.Health = Hum.MaxHealth
            end
            Hum.MaxHealth = math.huge
            Hum.Health = math.huge
            Hum:SetStateEnabled(Enum.HumanoidStateType.Dead, false)
            Hum.BreakJointsOnDeath = false
            Hum.RequiresNeck = false
        end)
    end)

    print("========================================")
    print("[VOIDCXZ] HUMANOID REPLACE + ANTI DEATH COMPLETE")
    print("========================================")
end

-- ==================================================
-- ENABLE / DISABLE / TOGGLE
-- ==================================================
local function EnableGodMode()
    GodModeEnabled = true
    task.spawn(RunGodMode)
    print("[VOIDCXZ] God Mode: ON")
end

local function DisableGodMode()
    GodModeEnabled = false
    if GodModeConnection then
        GodModeConnection:Disconnect()
        GodModeConnection = nil
    end
    print("[VOIDCXZ] God Mode: OFF")
end

local function ToggleGodMode()
    if GodModeEnabled then
        DisableGodMode()
    else
        EnableGodMode()
    end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_GodMode = {
    Toggle = ToggleGodMode,
    Enable = EnableGodMode,
    Disable = DisableGodMode,
    IsEnabled = function() return GodModeEnabled end
}

print("✅ GodMode Feature Loaded")
]]
__VOIDCXZ_SOURCE[[[Features/ManagerDrone.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Manager Drone
-- គ្រប់គ្រង Event → ហៅ Attack ឬ AFK
-- ✅ Event ចេញ → Stop AFK → Jump Out → Call Attack
--    (AttackDrone គ្រប់គ្រង Fly TP ទៅ Safe Zone ខ្លួនឯង)
-- ✅ Event Sec <= 10 → Stop Attack → Call AFK
-- ✅ Stop ពេល Disable
-- ✅ Restart ពេល Character Added
-- ==================================================

local Players = game:GetService("Players")

local Player = Players.LocalPlayer

-- ==================================================
-- SETTINGS
-- ==================================================
local EVENT_CHECK_INTERVAL = 1
local EVENT_STOP_ATTACK_THRESHOLD = 10
local SAFE_WAIT_TIME = 1
local SAFE_ZONE = Vector3.new(533, 70, -366)
local AFK_JUMP_WAIT = 0.5

-- ==================================================
-- STATE
-- ==================================================
local ManagerEnabled = false
local LastEventSec = 0
local LastEventText = ""
local ManagerThread = nil

-- ==================================================
-- GET EVENT INFO
-- ==================================================
local function GetEventInfo()
    local Success, Value = pcall(function()
        return game:GetService("Players").LocalPlayer.PlayerGui
            .HUD.GameHUD.BottomRight.ExperimentTimer.Value.Text
    end)
    if not Success or not Value then
        return 0, "", false
    end

    local Text = tostring(Value)

    local HasEventEnds = string.find(Text, "Event ends") ~= nil
    local IsEventActive = HasEventEnds

    local M = tonumber(string.match(Text, "(%d+)m")) or 0
    local S = tonumber(string.match(Text, "(%d+)s")) or 0
    local TotalSec = M * 60 + S

    return TotalSec, Text, IsEventActive
end

-- ==================================================
-- FORCE STOP ALL FEATURES
-- ==================================================
local function ForceStopAll()
    print("[ManagerDrone] Force Stop All Features")

    if _G.VOIDCXZ_AttackDrone then
        pcall(function() _G.VOIDCXZ_AttackDrone.Stop() end)
    end
    if _G.VOIDCXZ_AFKSystem then
        pcall(function() _G.VOIDCXZ_AFKSystem.Disable() end)
    end
end

-- ==================================================
-- SWITCH FROM AFK TO ATTACK
-- Event ចេញ → Stop AFK → Jump Out → Call Attack
-- AttackDrone គ្រប់គ្រង Fly TP ទៅ Safe Zone ខ្លួនឯង
-- ==================================================
local function SwitchAFKToAttack()
    print("[ManagerDrone] Event Detected → Switch AFK to Attack")

    -- 1. រក Treadmill Pos
    local TreadmillPos = nil
    if _G.VOIDCXZ_AFKSystem then
        TreadmillPos = _G.VOIDCXZ_AFKSystem.GetMyTreadmillPos()
    end

    if not TreadmillPos and _G.VOIDCXZ_AFKSystem then
        local _, Treadmill = _G.VOIDCXZ_AFKSystem.FindMyPlotAndTreadmill()
        if Treadmill then
            TreadmillPos = Treadmill.Position
        end
    end

    if not TreadmillPos then
        print("[ManagerDrone] No Treadmill → Stop AFK → Call Attack")
        if _G.VOIDCXZ_AFKSystem then
            _G.VOIDCXZ_AFKSystem.Disable()
        end
        task.wait(0.5)
        if _G.VOIDCXZ_AttackDrone then
            _G.VOIDCXZ_AttackDrone.Start()
        end
        return
    end

    -- 2. Jump ចេញពី Treadmill រហូតដល់ Dist > 5
    print("[ManagerDrone] Jumping out of Treadmill...")
    _G.VOIDCXZ_AFKSystem.JumpOutTreadmill(TreadmillPos, function()
        print("[ManagerDrone] ✅ Jumped out!")

        -- 3. Stop AFK (បិទ AFKEnabled → FlyTP របស់ AFKSystem ឈប់)
        if _G.VOIDCXZ_AFKSystem then
            _G.VOIDCXZ_AFKSystem.Disable()
        end

        task.wait(AFK_JUMP_WAIT)

        -- 4. ហៅ Attack Drone (AttackDrone គ្រប់គ្រង Fly TP ទៅ Safe Zone ខ្លួនឯង)
        print("[ManagerDrone] Call Attack Drone → Fly TP to Safe Zone → Spawn Loop")
        if _G.VOIDCXZ_AttackDrone then
            _G.VOIDCXZ_AttackDrone.Start()
        end
    end)
end

-- ==================================================
-- MAIN LOOP
-- ==================================================
local function MainLoop()
    while ManagerEnabled do
        local EventSec, EventText, IsEventActive = GetEventInfo()

        local EventNotActive = not IsEventActive
        local EventStopAttack = IsEventActive and EventSec > 0 and EventSec <= EVENT_STOP_ATTACK_THRESHOLD
        local EventActive = IsEventActive and EventSec > EVENT_STOP_ATTACK_THRESHOLD

        print("[ManagerDrone] Text:", EventText, "| Sec:", EventSec, "| IsActive:", IsEventActive, "| NotActive:", EventNotActive, "| StopAttack:", EventStopAttack, "| Active:", EventActive)

        -- ==================================================
        -- Event មិនទាន់ចេញ (Text = "in Xm Ys") → AFK System
        -- ==================================================
        if EventNotActive then
            if _G.VOIDCXZ_AttackDrone and _G.VOIDCXZ_AttackDrone.IsEnabled() then
                print("[ManagerDrone] Event Not Active → Stop Attack")
                _G.VOIDCXZ_AttackDrone.Stop()
            end

            if _G.VOIDCXZ_AFKSystem and not _G.VOIDCXZ_AFKSystem.IsEnabled() then
                print("[ManagerDrone] Event Not Active → AFK System")
                _G.VOIDCXZ_AFKSystem.Enable()
            end
        -- ==================================================
        -- Event ជិតចប់ (Sec <= 10) → Stop Attack → AFK
        -- ==================================================
        elseif EventStopAttack then
            if _G.VOIDCXZ_AttackDrone and _G.VOIDCXZ_AttackDrone.IsEnabled() then
                print("[ManagerDrone] Event <= 10s → Stop Attack → AFK System")
                _G.VOIDCXZ_AttackDrone.Stop()
            end

            if _G.VOIDCXZ_AFKSystem and not _G.VOIDCXZ_AFKSystem.IsEnabled() then
                _G.VOIDCXZ_AFKSystem.Enable()
            end
        -- ==================================================
        -- Event ចេញ (Sec > 10) → Switch AFK → Attack
        -- ==================================================
        elseif EventActive then
            if _G.VOIDCXZ_AFKSystem and _G.VOIDCXZ_AFKSystem.IsEnabled() then
                print("[ManagerDrone] Event Active → Switch AFK to Attack")
                SwitchAFKToAttack()
            elseif _G.VOIDCXZ_AttackDrone and not _G.VOIDCXZ_AttackDrone.IsEnabled() then
                print("[ManagerDrone] Event Active → Attack Drone")
                _G.VOIDCXZ_AttackDrone.Start()
            end
        end

        LastEventSec = EventSec
        LastEventText = EventText
        task.wait(EVENT_CHECK_INTERVAL)
    end

    ForceStopAll()
    print("[ManagerDrone] MainLoop Stopped")
end

-- ==================================================
-- ENABLE / DISABLE
-- ==================================================
local function EnableManager()
    if ManagerEnabled then return end
    ManagerEnabled = true

    if ManagerThread then
        pcall(function() task.cancel(ManagerThread) end)
        ManagerThread = nil
    end

    ManagerThread = task.spawn(function() MainLoop() end)

    print("[ManagerDrone] Manager Drone: ON")
end

local function DisableManager()
    if not ManagerEnabled then return end
    ManagerEnabled = false

    if ManagerThread then
        pcall(function() task.cancel(ManagerThread) end)
        ManagerThread = nil
    end

    ForceStopAll()

    print("[ManagerDrone] Manager Drone: OFF")
end

local function ToggleManager()
    if ManagerEnabled then
        DisableManager()
    else
        EnableManager()
    end
end

-- ==================================================
-- AUTO RE-APPLY ON CHARACTER ADDED
-- ==================================================
Player.CharacterAdded:Connect(function(Char)
    if ManagerEnabled then
        print("[ManagerDrone] Character Added → Restarting Manager...")
        task.wait(1)

        LastEventSec = 0
        LastEventText = ""

        if ManagerThread then
            pcall(function() task.cancel(ManagerThread) end)
            ManagerThread = nil
        end

        ManagerThread = task.spawn(function() MainLoop() end)

        print("[ManagerDrone] ✅ Re-applied on new Character")
    end
end)

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_ManagerDrone = {
    Enable = EnableManager,
    Disable = DisableManager,
    Toggle = ToggleManager,
    IsEnabled = function() return ManagerEnabled end,
    GetEventInfo = GetEventInfo,
    ForceStopAll = ForceStopAll,
    SwitchAFKToAttack = SwitchAFKToAttack,
}

print("✅ ManagerDrone Feature Loaded (Switch AFK to Attack)")
]]
__VOIDCXZ_SOURCE[[[Features/ManualFastClick.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Manual Fast Click
-- Enable Click Egg Fast by hand
-- Set ProximityPrompt HoldDuration = 0
-- ==================================================

local ProximityPromptService = game:GetService("ProximityPromptService")
local RunService = game:GetService("RunService")

-- ==================================================
-- STATE
-- ==================================================
local ManualFastClickEnabled = false
local PromptConnection = nil
local HeartbeatConnection = nil

-- ==================================================
-- SET HOLD DURATION = 0
-- ==================================================
local function ApplyHoldDuration(prompt)
    if not prompt then return end
    pcall(function()
        prompt.HoldDuration = 0
    end)
end

-- ==================================================
-- SCAN ALL EXISTING PROMPTS
-- ==================================================
local function ScanAllPrompts()
    -- រក ProximityPrompt ទាំងអស់ក្នុង workspace
    for _, descendant in ipairs(workspace:GetDescendants()) do
        if descendant:IsA("ProximityPrompt") then
            ApplyHoldDuration(descendant)
        end
    end

    -- រកក្នុង PlayerGui ដែរ (បើមាន)
    local Player = game.Players.LocalPlayer
    if Player then
        local PlayerGui = Player:FindFirstChild("PlayerGui")
        if PlayerGui then
            for _, descendant in ipairs(PlayerGui:GetDescendants()) do
                if descendant:IsA("ProximityPrompt") then
                    ApplyHoldDuration(descendant)
                end
            end
        end
    end
end

-- ==================================================
-- ENABLE
-- ==================================================
local function EnableManualFastClick()
    if ManualFastClickEnabled then return end
    ManualFastClickEnabled = true

    -- 1. Apply ភ្លាមទៅ prompt ដែលមានស្រាប់
    ScanAllPrompts()

    -- 2. ចាប់ព្រឹត្តិការណ៍ PromptShown សម្រាប់ prompt ថ្មី
    if PromptConnection then
        PromptConnection:Disconnect()
        PromptConnection = nil
    end
    PromptConnection = ProximityPromptService.PromptShown:Connect(function(prompt)
        if not ManualFastClickEnabled then return end
        ApplyHoldDuration(prompt)
    end)

    -- 3. Heartbeat Scan ជាប់ៗ ដើម្បីធានាថា prompt ថ្មីៗត្រូវបានកែ
    if HeartbeatConnection then
        HeartbeatConnection:Disconnect()
        HeartbeatConnection = nil
    end
    local Counter = 0
    HeartbeatConnection = RunService.Heartbeat:Connect(function()
        if not ManualFastClickEnabled then return end
        Counter = Counter + 1
        if Counter >= 30 then -- រាល់ ~0.5s
            Counter = 0
            ScanAllPrompts()
        end
    end)

    print("[VOIDCXZ] Manual Fast Click: ON")
end

-- ==================================================
-- DISABLE
-- ==================================================
local function DisableManualFastClick()
    if not ManualFastClickEnabled then return end
    ManualFastClickEnabled = false

    if PromptConnection then
        PromptConnection:Disconnect()
        PromptConnection = nil
    end
    if HeartbeatConnection then
        HeartbeatConnection:Disconnect()
        HeartbeatConnection = nil
    end

    print("[VOIDCXZ] Manual Fast Click: OFF")
end

-- ==================================================
-- TOGGLE
-- ==================================================
local function ToggleManualFastClick()
    if ManualFastClickEnabled then
        DisableManualFastClick()
    else
        EnableManualFastClick()
    end
end

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_ManualFastClick = {
    Enable = EnableManualFastClick,
    Disable = DisableManualFastClick,
    Toggle = ToggleManualFastClick,
    IsEnabled = function() return ManualFastClickEnabled end,
    ScanAllPrompts = ScanAllPrompts,
    ApplyHoldDuration = ApplyHoldDuration
}

print("✅ ManualFastClick Feature Loaded")
]]
__VOIDCXZ_SOURCE[[[Features/Sound.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Sound System (v3 — Play Once)
-- ✅ 1 Sound Only
-- ✅ Load ពេល Execute
-- ✅ លេងតែម្តង (No Loop)
-- ==================================================

local SoundService = game:GetService("SoundService")

-- ==================================================
-- CONFIG
-- ==================================================
local AUDIO_FOLDER = "VOIDCXZ-audio"
local AUDIO_FILE = AUDIO_FOLDER .. "/audio.mp3"
local AUDIO_LINK = "https://files.catbox.moe/yn5vzu.mp3"

-- ==================================================
-- ENSURE FOLDER
-- ==================================================
pcall(function()
    if not isfolder(AUDIO_FOLDER) then
        makefolder(AUDIO_FOLDER)
        print("📁 Created folder: " .. AUDIO_FOLDER)
    end
end)

-- ==================================================
-- DOWNLOAD AUDIO
-- ==================================================
if not isfile(AUDIO_FILE) then
    print("📥 កំពុងទាញយក Audio...")
    local ok, data = pcall(function() return game:HttpGet(AUDIO_LINK) end)
    if ok and data then
        writefile(AUDIO_FILE, data)
        print("✅ រក្សាទុក Audio រួច!")
    else
        warn("❌ ទាញយក Audio បរាជ័យ!")
    end
end

-- ==================================================
-- GET CUSTOM ASSET
-- ==================================================
local AudioAsset
pcall(function() AudioAsset = getcustomasset(AUDIO_FILE) end)

-- ==================================================
-- CREATE SOUND
-- ==================================================
pcall(function()
    local old = SoundService:FindFirstChild("VoidcxzAudio")
    if old then old:Destroy() end
end)

local Sound = Instance.new("Sound")
Sound.Name = "VoidcxzAudio"
Sound.SoundId = AudioAsset or ""
Sound.Volume = 1
Sound.Looped = false  -- ✅ លេងតែម្តង (No Loop)
Sound.Parent = SoundService

-- ==================================================
-- ✅ PLAY ONCE
-- ==================================================
local HasPlayed = false  -- ✅ Flag — Play Once

local function PlayAudio()
    -- ✅ បើលេងរួចហើយ → Skip
    if HasPlayed then
        print("⚠️ Audio លេងរួចហើយ (Play Once)")
        return
    end
    
    if Sound.SoundId and Sound.SoundId ~= "" then
        HasPlayed = true
        pcall(function() Sound:Play() end)
        print("🔊 Audio: PLAYING (Once)")
    end
end

local function StopAudio()
    if Sound.IsPlaying then
        pcall(function() Sound:Stop() end)
        print("🔇 Audio: STOPPED")
    end
end

-- ==================================================
-- ✅ EXPORT
-- ==================================================
_G.VOIDCXZ_Sound = {
    Play = PlayAudio,
    Stop = StopAudio,
    IsPlaying = function() return Sound.IsPlaying end,
    HasPlayed = function() return HasPlayed end,
    Sound = Sound,
    Folder = AUDIO_FOLDER,
    AudioFile = AUDIO_FILE,
}

print("✅ Sound Feature Loaded (Play Once)")
]]
__VOIDCXZ_SOURCE[[[Features/SpeedLock.lua]]] = [[-- ==================================================
-- VOIDCXZ HUB | FEATURE | Speed Lock System (v6 FINAL)
-- ✅ Emoji 🔒 លើ Button ពេល Speed < 1B
-- ✅ ដក 🔒 ចេញ ពេល Speed ≥ 1B
-- ✅ Show Message
-- ✅ Safe Call
-- ==================================================

local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local CoreGui = game:GetService("CoreGui")

local Player = Players.LocalPlayer

-- ==================================================
-- CONFIG
-- ==================================================
local CONFIG = {
    RequiredSpeed = 1000000000,  -- 1B
    MessageDuration = 5,
}

-- ==================================================
-- STATE
-- ==================================================
local IsUnlocked = false
local SpeedValue = nil
local LockedButtons = {}
local OriginalButtonData = {}  -- ✅ Store Original Data

-- ==================================================
-- SAFE CALL
-- ==================================================
local function SafeCall(func, ...)
    if not func then return false end
    local args = {...}
    local Success, Err = pcall(function()
        func(table.unpack(args))
    end)
    if not Success then
        warn("[SpeedLock] Error:", Err)
    end
    return Success
end

-- ==================================================
-- GET SPEED VALUE
-- ==================================================
local function GetSpeedValue()
    local Leaderstats = Player:FindFirstChild("leaderstats")
    if Leaderstats then
        local Speed = Leaderstats:FindFirstChild("Speed")
        if Speed then return Speed end
    end
    
    local PlayerGui = Player:FindFirstChild("PlayerGui")
    if PlayerGui then
        for _, descendant in ipairs(PlayerGui:GetDescendants()) do
            if descendant.Name == "Speed" and 
               (descendant:IsA("NumberValue") or descendant:IsA("IntValue")) then
                return descendant
            end
        end
    end
    
    return nil
end

-- ==================================================
-- FORMAT NUMBER
-- ==================================================
local function FormatNumber(num)
    if type(num) ~= "number" then return tostring(num) end
    
    if num >= 1e12 then
        return string.format("%.2fT", num / 1e12)
    elseif num >= 1e9 then
        return string.format("%.2fB", num / 1e9)
    elseif num >= 1e6 then
        return string.format("%.2fM", num / 1e6)
    elseif num >= 1e3 then
        return string.format("%.2fK", num / 1e3)
    else
        return tostring(math.floor(num))
    end
end

-- ==================================================
-- CHECK SPEED
-- ==================================================
local function CheckSpeed()
    SpeedValue = GetSpeedValue()
    
    if not SpeedValue then
        warn("[SpeedLock] ⚠️ Speed Value not found!")
        return false
    end
    
    local CurrentSpeed = math.floor(tonumber(SpeedValue.Value) or 0)
    local RequiredSpeed = math.floor(CONFIG.RequiredSpeed)
    
    print("[SpeedLock] 📊 Current:", FormatNumber(CurrentSpeed))
    print("[SpeedLock] 📊 Required:", FormatNumber(RequiredSpeed))
    
    return CurrentSpeed >= RequiredSpeed
end

-- ==================================================
-- SHOW MESSAGE
-- ==================================================
local function ShowMessage(Text, Duration)
    pcall(function()
        local Old = CoreGui:FindFirstChild("SpeedLockMessage")
        if Old then Old:Destroy() end
    end)
    
    local MessageGui = Instance.new("ScreenGui")
    MessageGui.Name = "SpeedLockMessage"
    MessageGui.ResetOnSpawn = false
    MessageGui.IgnoreGuiInset = true
    MessageGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    MessageGui.DisplayOrder = 99999
    MessageGui.Parent = CoreGui
    
    local Container = Instance.new("Frame")
    Container.Name = "Container"
    Container.Size = UDim2.new(0, 420, 0, 75)
    Container.Position = UDim2.new(0.5, -210, 0, -95)
    Container.BackgroundColor3 = Color3.fromRGB(20, 21, 30)
    Container.BackgroundTransparency = 0.05
    Container.BorderSizePixel = 0
    Container.Parent = MessageGui
    
    local ContainerCorner = Instance.new("UICorner")
    ContainerCorner.CornerRadius = UDim.new(0, 12)
    ContainerCorner.Parent = Container
    
    local ContainerStroke = Instance.new("UIStroke")
    ContainerStroke.Color = Color3.fromRGB(255, 80, 80)
    ContainerStroke.Thickness = 2
    ContainerStroke.Transparency = 0.2
    ContainerStroke.Parent = Container
    
    local LockIcon = Instance.new("ImageLabel")
    LockIcon.Size = UDim2.new(0, 38, 0, 38)
    LockIcon.Position = UDim2.new(0, 14, 0.5, -19)
    LockIcon.BackgroundTransparency = 1
    LockIcon.Image = "rbxassetid://6031090990"
    LockIcon.ImageColor3 = Color3.fromRGB(255, 80, 80)
    LockIcon.Parent = Container
    
    local TextLabel = Instance.new("TextLabel")
    TextLabel.Size = UDim2.new(1, -64, 1, 0)
    TextLabel.Position = UDim2.new(0, 60, 0, 0)
    TextLabel.BackgroundTransparency = 1
    TextLabel.Text = Text
    TextLabel.TextColor3 = Color3.fromRGB(255, 255, 255)
    TextLabel.TextSize = 13
    TextLabel.TextXAlignment = Enum.TextXAlignment.Left
    TextLabel.TextYAlignment = Enum.TextYAlignment.Center
    TextLabel.Font = Enum.Font.GothamBold
    TextLabel.TextWrapped = true
    TextLabel.Parent = Container
    
    TweenService:Create(Container, TweenInfo.new(0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {
        Position = UDim2.new(0.5, -210, 0, 80)
    }):Play()
    
    task.delay(Duration or CONFIG.MessageDuration, function()
        if Container and Container.Parent then
            TweenService:Create(Container, TweenInfo.new(0.3), {
                Position = UDim2.new(0.5, -210, 0, -95),
                BackgroundTransparency = 1
            }):Play()
            TweenService:Create(TextLabel, TweenInfo.new(0.3), {TextTransparency = 1}):Play()
            TweenService:Create(LockIcon, TweenInfo.new(0.3), {ImageTransparency = 1}):Play()
            TweenService:Create(ContainerStroke, TweenInfo.new(0.3), {Transparency = 1}):Play()
            
            task.delay(0.35, function()
                if MessageGui then MessageGui:Destroy() end
            end)
        end
    end)
end

-- ==================================================
-- REGISTER LOCKABLE BUTTON
-- ==================================================
local function RegisterLockableButton(Button, Name)
    if not Button then return end
    
    -- ✅ Store Original Data
    table.insert(OriginalButtonData, {
        Button = Button,
        OriginalText = Button.Text,
        OriginalTextSize = Button.TextSize,
        OriginalTextColor3 = Button.TextColor3,
        OriginalFont = Button.Font,
        OriginalBackgroundColor3 = Button.BackgroundColor3,
        OriginalBackgroundTransparency = Button.BackgroundTransparency,
    })
    
    table.insert(LockedButtons, {
        Button = Button,
        Name = Name or Button.Name,
    })
    
    print("[SpeedLock] 📝 Registered:", Name or Button.Name)
end

-- ==================================================
-- ✅ APPLY LOCK (ដាក់ Emoji 🔒)
-- ==================================================
local function ApplyLockToAll()
    for _, data in ipairs(LockedButtons) do
        local Button = data.Button
        if Button and Button.Parent then
            -- ✅ ដាក់ Emoji 🔒 លើ Button
            Button.Text = "🔒"
            Button.TextSize = 20
            Button.TextColor3 = Color3.fromRGB(255, 80, 80)
            Button.Font = Enum.Font.GothamBold
            
            -- ✅ Background ក្រហមស្រាល
            Button.BackgroundColor3 = Color3.fromRGB(40, 20, 20)
            Button.BackgroundTransparency = 0.3
            
            -- ✅ Stroke ក្រហម
            local Stroke = Button:FindFirstChildOfClass("UIStroke")
            if Stroke then
                Stroke.Color = Color3.fromRGB(255, 80, 80)
                Stroke.Thickness = 2
                Stroke.Transparency = 0.2
            end
            
            -- ✅ Disable Button
            Button.Active = false
            Button.Selectable = false
        end
    end
    
    print("[SpeedLock] 🔒 Applied Lock to", #LockedButtons, "buttons")
end

-- ==================================================
-- ✅ REMOVE LOCK (ដក Emoji 🔒 ចេញ)
-- ==================================================
local function RemoveLockFromAll()
    -- ✅ Restore Original Data
    for _, data in ipairs(OriginalButtonData) do
        local Button = data.Button
        if Button and Button.Parent then
            Button.Text = data.OriginalText or ""
            Button.TextSize = data.OriginalTextSize or 14
            Button.TextColor3 = data.OriginalTextColor3 or Color3.fromRGB(255, 255, 255)
            Button.Font = data.OriginalFont or Enum.Font.GothamBold
            
            Button.BackgroundColor3 = data.OriginalBackgroundColor3 or Color3.fromRGB(28, 29, 39)
            Button.BackgroundTransparency = data.OriginalBackgroundTransparency or 0
            
            -- ✅ Stroke ត្រលប់ដើម
            local Stroke = Button:FindFirstChildOfClass("UIStroke")
            if Stroke then
                Stroke.Color = Color3.fromRGB(200, 200, 220)
                Stroke.Thickness = 1.5
                Stroke.Transparency = 0
            end
            
            Button.Active = true
            Button.Selectable = true
        end
    end
    
    print("[SpeedLock] 🔓 Removed Lock from", #LockedButtons, "buttons")
end

-- ==================================================
-- MAIN CHECK
-- ==================================================
local function RunCheck()
    print("[SpeedLock] ================================")
    print("[SpeedLock] 🔍 Checking Speed...")
    print("[SpeedLock] ================================")
    
    IsUnlocked = CheckSpeed()
    
    if IsUnlocked then
        print("[SpeedLock] 🎉 UNLOCKED!")
        RemoveLockFromAll()
    else
        print("[SpeedLock] 🔒 LOCKED!")
        ApplyLockToAll()
    end
    
    print("[SpeedLock] ================================")
end

-- ==================================================
-- PUBLIC API
-- ==================================================
local SpeedLock = {}

SpeedLock.IsUnlocked = function() return IsUnlocked end
SpeedLock.GetSpeed = function()
    if not SpeedValue then SpeedValue = GetSpeedValue() end
    return SpeedValue and math.floor(tonumber(SpeedValue.Value) or 0) or 0
end
SpeedLock.GetRequiredSpeed = function() return CONFIG.RequiredSpeed end
SpeedLock.FormatNumber = function(num) return FormatNumber(num) end
SpeedLock.ShowMessage = ShowMessage

SpeedLock.RegisterLockable = RegisterLockableButton
SpeedLock.RunCheck = RunCheck
SpeedLock.ApplyLock = ApplyLockToAll
SpeedLock.RemoveLock = RemoveLockFromAll

-- ==================================================
-- EXPORT
-- ==================================================
_G.VOIDCXZ_SpeedLock = SpeedLock

print("✅ Speed Lock System Loaded (v6 — Emoji 🔒)")
]]
__VOIDCXZ_SOURCE[[[Features/TeleportSystem.lua]]] = [[
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Player = Players.LocalPlayer
local Container = workspace:WaitForChild("AreaEggSlotsClient")

-- ==================================================
-- CONFIG
-- ==================================================
local Config = {
    ArriveDistance = 2,
    LockDistance = 1,
    FlyTPDistance = 20,
    FlyOffset = 3,
    StopShotDistance = 1200,
    ShotTPTime = 1.20,
    ShotTPTime2 = 1.10,
    PushUpOffset = 50,
    PlayerCheckDistance = 30,
    LockWait = 0.1,
    RecoverDistanceThreshold = 500,
    MaxRepeatCount = 10,
    CollectTargetTimeout = 20,

    -- ✅ Step 8b: Wait + Top2
    Top2ShortTPWait = 0.01,     -- ✅ Wait 1s មុន Short TP
    Top2ShotTPTime = 0.01,      -- ✅ Short TP Time (1s)
    Top2StopDistance = 4,    -- ✅ Stop Distance

    Position1_Top1 = Vector3.new(612, 70, -333),
    Position1_Top2 = Vector3.new(546, 70, -309),
    Position2_Top1 = Vector3.new(602, 70, -410),
    Position2_Top2 = Vector3.new(541, 70, -414),

    CollectInterval = 0.02,
    MaxCollectAttempts = 10000,
    EggGoneCheckInterval = 0.5,
}

-- ==================================================
-- MAP POSITIONS
-- ==================================================
local MapPositions = {
    {Pos = Vector3.new(5666, 70, -329), MapId = 1},
    {Pos = Vector3.new(4798, 70, -333), MapId = 2},
    {Pos = Vector3.new(4031, 70, -396), MapId = 3},
    {Pos = Vector3.new(3397, 70, -328), MapId = 4},
    {Pos = Vector3.new(2815, 70, -398), MapId = 5},
    {Pos = Vector3.new(2286, 70, -331), MapId = 6},
    {Pos = Vector3.new(1877, 70, -390), MapId = 7},
    {Pos = Vector3.new(1488, 70, -318), MapId = 8},
    {Pos = Vector3.new(1187, 70, -406), MapId = 9},
    {Pos = Vector3.new(950, 70, -328), MapId = 10},
    {Pos = Vector3.new(6703, 70, -349), MapId = 11},
}

-- ==================================================
-- REMOTES
-- ==================================================
local CollectEvent = ReplicatedStorage.Packages.Networking:FindFirstChild("RF/EggWorld/AskFieldEggCarry")
local DropEvent = ReplicatedStorage.Packages.Networking:FindFirstChild("RF/EggWorld/AskFieldEggDrop")

if not CollectEvent then warn("[TeleportSystem] CollectEvent not found") return end
if not DropEvent then warn("[TeleportSystem] DropEvent not found") return end

print("[TeleportSystem] CollectEvent + DropEvent OK")

-- ==================================================
-- STATE
-- ==================================================
local State = {
    Running = false,
    Step = "idle",
    FirstEggUid = nil,
    FirstEggSlotKey = nil,
    TargetUid = nil,

    WalkConnection = nil,
    FlyConnection = nil,
    LockConnection = nil,

    DropHeldEgg = nil,
    DropHeldEggConnection = nil,

    FirstCollected = false,
    TargetCollected = false,
    CollectedAgain = false,
    DropDone = false,
    CollectAttempts = 0,

    SavedWalkSpeed = nil,
    SavedJumpPower = nil,
    SavedJumpHeight = nil,
    SavedUseJumpPower = nil,

    FlySequence = 0,
    FirstDropDone = false,
    RepeatCount = 0,
    IsRecoverMode = false,

    SafePosition = nil,
    SafeName = nil,
    CurrentEggUid = nil,
    EggGoneCheckThread = nil,

    OnComplete = nil,
}

-- ==================================================
-- FORWARD DECLARATIONS
-- ==================================================
local GetHumanoid
local GetPosition
local SavePlayerStats
local RestoreStats
local CleanupMovers
local IsEggGone
local GetNearestMapWait
local GetSafePosition
local GetPlayerSpeed
local FindNearestFirstEgg
local PushUp
local CFrameInstant
local RemoteCollectFirst
local RemoteCollectTarget
local RemoteDrop
local StartLock
local StopLock
local FlyTPAndLock
local ShotTP
local ShotTPWithStop
local WalkTP
local AutoStop
local Step1_WalkToFirstEgg
local Step3b_AfterDropFirst
local Step4_WalkToTargetAndFlyLock
local Step7_ShotToSafePosition
local Step8b_WalkToCollectAgain
local Step8c_CheckDistanceAndRecover
local Step9_WalkToSwapPosition
local StartEggGoneCheck
local SetupDropHeldEgg
local StartProcess
local FullReset
local NotifyComplete

-- ==================================================
-- UTILS
-- ==================================================
GetHumanoid = function()
    local Char = Player.Character
    if not Char then return nil, nil end
    return Char:FindFirstChildOfClass("Humanoid"), Char:FindFirstChild("HumanoidRootPart")
end

GetPosition = function(Object)
    if not Object then return nil end
    if Object:IsA("Model") then
        if Object.PrimaryPart then return Object.PrimaryPart.Position end
        local Part = Object:FindFirstChildWhichIsA("BasePart")
        if Part then return Part.Position end
        for _, Desc in ipairs(Object:GetDescendants()) do
            if Desc:IsA("BasePart") then return Desc.Position end
        end
    elseif Object:IsA("BasePart") then
        return Object.Position
    end
    return nil
end

GetPlayerSpeed = function()
    if State.SavedWalkSpeed and State.SavedWalkSpeed > 0 then
        return State.SavedWalkSpeed
    end
    local Hum = GetHumanoid()
    if Hum then return Hum.WalkSpeed end
    return 16
end

FindNearestFirstEgg = function()
    local Hum, Root = GetHumanoid()
    if not Root then return nil, nil end
    
    local PlayerPos = Root.Position
    local NearestEggUid = nil
    local NearestSlotKey = nil
    local NearestDist = math.huge
    
    for _, child in ipairs(Container:GetChildren()) do
        if string.find(child.Name, "FirstAreaEgg") then
            local EggPos = GetPosition(child)
            if EggPos then
                local Dist = (EggPos - PlayerPos).Magnitude
                if Dist < NearestDist then
                    NearestDist = Dist
                    NearestEggUid = child.Name
                    local SlotNum = string.match(child.Name, "Slot_(%d+)")
                    if SlotNum then
                        NearestSlotKey = "Forest:Slot_" .. SlotNum
                    end
                end
            end
        end
    end
    
    if NearestEggUid then
        print(string.format("[TeleportSystem] 🥚 Nearest First Egg: %s | Dist: %.1f", NearestEggUid, NearestDist))
    end
    
    return NearestEggUid, NearestSlotKey
end

SavePlayerStats = function()
    local Hum = GetHumanoid()
    if not Hum then return end

    State.SavedWalkSpeed = Hum.WalkSpeed
    State.SavedJumpPower = Hum.JumpPower
    State.SavedJumpHeight = Hum.JumpHeight
    State.SavedUseJumpPower = Hum.UseJumpPower

    print(string.format("[TeleportSystem] ✅ Saved WalkSpeed: %.1f", State.SavedWalkSpeed))
end

RestoreStats = function()
    local Hum = GetHumanoid()
    if not Hum then return end

    if State.SavedWalkSpeed ~= nil then
        pcall(function() Hum.WalkSpeed = State.SavedWalkSpeed end)
        print(string.format("[TeleportSystem] ✅ Restored WalkSpeed: %.1f", State.SavedWalkSpeed))
    end
    if State.SavedJumpPower ~= nil then pcall(function() Hum.JumpPower = State.SavedJumpPower end) end
    if State.SavedJumpHeight ~= nil then pcall(function() Hum.JumpHeight = State.SavedJumpHeight end) end
    if State.SavedUseJumpPower ~= nil then pcall(function() Hum.UseJumpPower = State.SavedUseJumpPower end) end
end

CleanupMovers = function()
    if State.WalkConnection then State.WalkConnection:Disconnect() State.WalkConnection = nil end
    if State.FlyConnection then State.FlyConnection:Disconnect() State.FlyConnection = nil end
    if State.LockConnection then State.LockConnection:Disconnect() State.LockConnection = nil end

    local Hum, Root = GetHumanoid()
    if Hum then
        pcall(function()
            Hum.PlatformStand = false
            Hum.Sit = false
        end)
    end
    if Root then
        pcall(function()
            Root.AssemblyLinearVelocity = Vector3.zero
            Root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

IsEggGone = function(Uid)
    if not Uid then return true end
    local InWorkspace = workspace:FindFirstChild(Uid) ~= nil
    local InContainer = Container and Container:FindFirstChild(Uid) ~= nil
    if not InWorkspace and not InContainer then return true end
    return false
end

GetNearestMapWait = function(EggPos)
    if not EggPos then return 8 end
    
    local NearestDist = math.huge
    local NearestMapId = 1
    local NearestMapName = "Unknown"
    
    for _, MapData in ipairs(MapPositions) do
        local Dist = (EggPos - MapData.Pos).Magnitude
        if Dist < NearestDist then
            NearestDist = Dist
            NearestMapId = MapData.MapId
        end
    end
    
    local Wait = 8
    if _G.VOIDCXZ_MapSettings then
        Wait = _G.VOIDCXZ_MapSettings.GetMapWait(NearestMapId)
        local MapInfo = _G.VOIDCXZ_MapSettings.GetMapData(NearestMapId)
        if MapInfo then NearestMapName = MapInfo.Name end
    end
    
    print(string.format("[TeleportSystem] 🗺️ %s (Map %d) | Wait: %d", NearestMapName, NearestMapId, Wait))
    return Wait
end

GetSafePosition = function()
    local P1_Top1 = Config.Position1_Top1
    local P2_Top1 = Config.Position2_Top1
    local P1_Top1_MinDist = math.huge
    local P2_Top1_MinDist = math.huge

    for _, otherPlayer in ipairs(Players:GetPlayers()) do
        if otherPlayer ~= Player then
            local otherChar = otherPlayer.Character
            if otherChar then
                local otherRoot = otherChar:FindFirstChild("HumanoidRootPart")
                if otherRoot then
                    local pos = otherRoot.Position
                    local d1 = (pos - P1_Top1).Magnitude
                    local d2 = (pos - P2_Top1).Magnitude
                    if d1 < P1_Top1_MinDist then P1_Top1_MinDist = d1 end
                    if d2 < P2_Top1_MinDist then P2_Top1_MinDist = d2 end
                end
            end
        end
    end

    local SafePos = P1_Top1
    local SafeName = "P1_Top1"

    if P1_Top1_MinDist < Config.PlayerCheckDistance and P2_Top1_MinDist >= P1_Top1_MinDist then
        SafePos = P2_Top1
        SafeName = "P2_Top1"
    end

    State.SafePosition = SafePos
    State.SafeName = SafeName
    return SafePos, SafeName
end

PushUp = function(Offset, Callback)
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root then
        if Callback then Callback() end
        return
    end

    local TargetPos = Root.Position + Vector3.new(0, Offset, 0)
    pcall(function()
        Hum.PlatformStand = true
        Root.CFrame = CFrame.new(TargetPos)
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero
    end)

    if Callback then Callback() end
end

CFrameInstant = function(Destination, Callback)
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end
    pcall(function()
        Hum:MoveTo(Root.Position)
        Hum.WalkSpeed = 0
        Root.CFrame = CFrame.new(Destination)
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero
    end)
    if Callback then Callback() end
end

RemoteCollectFirst = function()
    if not CollectEvent or not State.FirstEggSlotKey or not State.FirstEggUid then return false end
    return pcall(function()
        return CollectEvent:InvokeServer({
            FirstAreaSlotKey = State.FirstEggSlotKey,
            Uid = State.FirstEggUid
        })
    end)
end

RemoteCollectTarget = function()
    if not CollectEvent or not State.TargetUid then return false end
    return pcall(function()
        return CollectEvent:InvokeServer({ Uid = State.TargetUid })
    end)
end

RemoteDrop = function()
    if not DropEvent then return false end
    local Success, Result = pcall(function()
        return DropEvent:InvokeServer({ Reason = "PlayerRequest" })
    end)
    return Success and Result
end

StartLock = function(TargetPos)
    if State.LockConnection then State.LockConnection:Disconnect() State.LockConnection = nil end
    local LockedCFrame = CFrame.new(TargetPos + Vector3.new(0, Config.LockDistance, 0))
    State.LockConnection = RunService.Heartbeat:Connect(function()
        if not State.Running then
            if State.LockConnection then State.LockConnection:Disconnect() State.LockConnection = nil end
            return
        end
        local _, Root = GetHumanoid()
        if not Root then return end
        Root.CFrame = LockedCFrame
        Root.AssemblyLinearVelocity = Vector3.zero
        Root.AssemblyAngularVelocity = Vector3.zero
    end)
end

StopLock = function()
    if State.LockConnection then
        State.LockConnection:Disconnect()
        State.LockConnection = nil
    end
end

FlyTPAndLock = function(Destination, YOffset, Callback)
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local PlayerSpeed = GetPlayerSpeed()
    print(string.format("[TeleportSystem] ✈️ FlyTP | Speed: %.1f", PlayerSpeed))

    State.FlySequence = State.FlySequence + 1
    local Seq = State.FlySequence
    local LockPos = Destination + Vector3.new(0, YOffset or Config.FlyOffset, 0)
    Hum.PlatformStand = true
    local StartTime = tick()

    State.FlyConnection = RunService.Heartbeat:Connect(function()
        if not State.Running then CleanupMovers() return end
        if Seq ~= State.FlySequence then
            if State.FlyConnection then State.FlyConnection:Disconnect() State.FlyConnection = nil end
            return
        end
        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 or Hum2.Health <= 0 then CleanupMovers() return end
        local CurrentPos = Root2.Position
        local Dir = LockPos - CurrentPos
        local Dist = Dir.Magnitude
        if Dist <= 3 then
            if State.FlyConnection then State.FlyConnection:Disconnect() State.FlyConnection = nil end
            CleanupMovers()
            Root2.CFrame = CFrame.new(LockPos)
            Root2.AssemblyLinearVelocity = Vector3.zero
            Root2.AssemblyAngularVelocity = Vector3.zero
            StartLock(LockPos)
            if Callback then Callback() end
            return
        end
        local MoveStep = Dir.Unit * PlayerSpeed * (1/60)
        Root2.CFrame = CFrame.new(CurrentPos + MoveStep)
        Root2.AssemblyLinearVelocity = Vector3.zero
        Root2.AssemblyAngularVelocity = Vector3.zero
        if tick() - StartTime > 10 then
            if State.FlyConnection then State.FlyConnection:Disconnect() State.FlyConnection = nil end
            CleanupMovers()
            Root2.CFrame = CFrame.new(LockPos)
            StartLock(LockPos)
            if Callback then Callback() end
        end
    end)
end

ShotTP = function(Destination, Time, CheckDrop, Callback)
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local PlayerSpeed = GetPlayerSpeed()
    print(string.format("[TeleportSystem] ✈️ ShotTP | Speed: %.1f", PlayerSpeed))

    local TargetCFrame = CFrame.new(Destination)
    local StartPos = Root.Position
    local StartTime = tick()
    Hum.PlatformStand = true
    local ShotStopRequested = false

    State.FlyConnection = RunService.Heartbeat:Connect(function()
        if not State.Running then CleanupMovers() return end
        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 or Hum2.Health <= 0 then CleanupMovers() return end
        local Elapsed = tick() - StartTime
        local Alpha = math.clamp(Elapsed / Time, 0, 1)
        local NewPos = StartPos:Lerp(Destination, Alpha)
        Root2.CFrame = CFrame.new(NewPos)
        Root2.AssemblyLinearVelocity = Vector3.zero
        Root2.AssemblyAngularVelocity = Vector3.zero
        local Dist = (Root2.Position - Destination).Magnitude
        
        if CheckDrop and not ShotStopRequested and Dist <= Config.StopShotDistance then
            ShotStopRequested = true
            if State.FlyConnection then State.FlyConnection:Disconnect() State.FlyConnection = nil end
            if Hum2 then Hum2.PlatformStand = false end
            RemoteDrop()
            if Callback then Callback() end
            return
        end
        
        if Dist <= Config.ArriveDistance or Alpha >= 1 then
            CleanupMovers()
            Root2.CFrame = TargetCFrame
            Root2.AssemblyLinearVelocity = Vector3.zero
            Root2.AssemblyAngularVelocity = Vector3.zero
            if Callback then Callback() end
        end
    end)
end

ShotTPWithStop = function(Destination, Time, StopDistance, Callback)
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local PlayerSpeed = GetPlayerSpeed()
    print(string.format("[TeleportSystem] ✈️ ShotTPWithStop | Speed: %.1f", PlayerSpeed))

    local StartPos = Root.Position
    local StartTime = tick()
    Hum.PlatformStand = true

    State.FlyConnection = RunService.Heartbeat:Connect(function()
        if not State.Running then CleanupMovers() return end
        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 or Hum2.Health <= 0 then CleanupMovers() return end

        local Elapsed = tick() - StartTime
        local Alpha = math.clamp(Elapsed / Time, 0, 1)
        local NewPos = StartPos:Lerp(Destination, Alpha)

        Root2.CFrame = CFrame.new(NewPos)
        Root2.AssemblyLinearVelocity = Vector3.zero
        Root2.AssemblyAngularVelocity = Vector3.zero

        local Dist = (Root2.Position - Destination).Magnitude

        if Dist <= StopDistance then
            if State.FlyConnection then State.FlyConnection:Disconnect() State.FlyConnection = nil end
            CleanupMovers()

            local DownPos = Vector3.new(Root2.Position.X, 70, Root2.Position.Z)
            Root2.CFrame = CFrame.new(DownPos)
            Root2.AssemblyLinearVelocity = Vector3.zero
            Root2.AssemblyAngularVelocity = Vector3.zero

            if Callback then Callback() end
            return
        end

        if Alpha >= 1 then
            CleanupMovers()
            if Callback then Callback() end
        end
    end)
end

WalkTP = function(Destination, LockAfterArrive, FlyAtDistance, DropAtDistance, Callback)
    CleanupMovers()
    local Hum, Root = GetHumanoid()
    if not Hum or not Root or Hum.Health <= 0 then
        if Callback then Callback() end
        return
    end

    local PlayerSpeed = GetPlayerSpeed()
    Hum.WalkSpeed = PlayerSpeed
    
    print(string.format("[TeleportSystem] 🚶 WalkTP | Speed: %.1f", PlayerSpeed))

    local LastCheck = 0
    local FlyDone = false
    local DropDone = false

    State.WalkConnection = RunService.Heartbeat:Connect(function()
        if not State.Running then CleanupMovers() return end
        local Hum2, Root2 = GetHumanoid()
        if not Hum2 or not Root2 or Hum2.Health <= 0 then CleanupMovers() return end
        
        Hum2.WalkSpeed = PlayerSpeed
        
        local Dist = (Root2.Position - Destination).Magnitude

        if FlyAtDistance and not FlyDone and Dist <= FlyAtDistance then
            FlyDone = true
            State.WalkConnection:Disconnect() State.WalkConnection = nil
            Hum2:MoveTo(Root2.Position)
            Hum2.WalkSpeed = 0
            FlyTPAndLock(Destination, Config.FlyOffset, function()
                if Callback then Callback() end
            end)
            return
        end

        if DropAtDistance and not DropDone and Dist <= DropAtDistance then
            DropDone = true
            RemoteDrop()
        end

        Hum2:MoveTo(Destination)

        if tick() - LastCheck > 0.05 then
            LastCheck = tick()
            if Dist <= Config.ArriveDistance then
                CleanupMovers()
                Hum2:MoveTo(Root2.Position)
                Hum2.WalkSpeed = 0
                if LockAfterArrive then StartLock(Destination) end
                if Callback then Callback() end
                return
            end
        end
    end)
end

NotifyComplete = function()
    print("[TeleportSystem] ✅ NotifyComplete → Call FarmingManager")
    if State.OnComplete then pcall(function() State.OnComplete() end) end
    if _G.VOIDCXZ_FarmingManager and _G.VOIDCXZ_FarmingManager.OnTeleportComplete then
        pcall(function() _G.VOIDCXZ_FarmingManager.OnTeleportComplete() end)
    end
end

AutoStop = function()
    StopLock()
    CleanupMovers()
    RestoreStats()
    State.Running = false
    State.Step = "done"
    State.FirstCollected = false
    State.TargetCollected = false
    State.CollectedAgain = false
    State.DropDone = false
    State.CollectAttempts = 0
    State.FirstDropDone = false
    State.RepeatCount = 0
    State.IsRecoverMode = false
    State.SafePosition = nil
    State.SafeName = nil
    State.CurrentEggUid = nil
    State.FirstEggUid = nil
    State.FirstEggSlotKey = nil

    if State.DropHeldEggConnection then
        State.DropHeldEggConnection:Disconnect()
        State.DropHeldEggConnection = nil
    end
    if State.EggGoneCheckThread then
        pcall(function() task.cancel(State.EggGoneCheckThread) end)
        State.EggGoneCheckThread = nil
    end

    print("[TeleportSystem] ✅ Auto Stop + Reset First Egg")
    NotifyComplete()
end

Step1_WalkToFirstEgg = function()
    State.Step = "1_to_first"
    local FirstEgg = Container:FindFirstChild(State.FirstEggUid)
    if not FirstEgg then AutoStop() return end
    local FirstPos = GetPosition(FirstEgg)
    if not FirstPos then AutoStop() return end

    WalkTP(FirstPos, false, Config.FlyTPDistance, false, function()
        State.Step = "2_collect_first"
        State.FirstCollected = false
        State.CurrentEggUid = State.FirstEggUid
        task.spawn(function()
            while State.Running and State.Step == "2_collect_first" do
                task.wait(Config.CollectInterval)
                RemoteCollectFirst()
                State.CollectAttempts = State.CollectAttempts + 1
                if State.CollectAttempts > Config.MaxCollectAttempts then AutoStop() return end
            end
        end)
    end)
end

Step3b_AfterDropFirst = function()
    if not State.Running then return end
    State.Step = "3b_after_drop"
    StopLock()

    PushUp(Config.PushUpOffset, function()
        local TargetPos
        if Container:FindFirstChild(State.TargetUid) then
            TargetPos = GetPosition(Container:FindFirstChild(State.TargetUid))
        elseif workspace:FindFirstChild(State.TargetUid) then
            TargetPos = GetPosition(workspace:FindFirstChild(State.TargetUid))
        end
        if not TargetPos then AutoStop() return end

        ShotTPWithStop(TargetPos, Config.ShotTPTime, Config.StopShotDistance, function()
            RemoteDrop()
            State.FirstDropDone = true
            print("[TeleportSystem] 🥚 First Egg Dropped")

            task.wait(0.3)

            WalkTP(TargetPos, false, Config.FlyTPDistance, false, function()
                task.spawn(function()
                    local WaitTime = GetNearestMapWait(TargetPos)
                    task.wait(WaitTime)
                    if not State.Running then return end
                    
                    State.Step = "6_collect_target"
                    State.TargetCollected = false
                    State.CurrentEggUid = State.TargetUid
                    
                    local CollectStartTime = tick()
                    
                    while State.Running and State.Step == "6_collect_target" do
                        task.wait(Config.CollectInterval)
                        RemoteCollectTarget()
                        
                        if tick() - CollectStartTime >= Config.CollectTargetTimeout then
                            warn(string.format("[TeleportSystem] ⏱️ Collect Timeout (%ds) → Skip", Config.CollectTargetTimeout))
                            State.Step = "6b_timeout"
                            task.wait(0.3)
                            Step7_ShotToSafePosition()
                            return
                        end
                    end
                end)
            end)
        end)
    end)
end

Step4_WalkToTargetAndFlyLock = function()
    if not State.Running then return end
    State.Step = "4_walk_target"

    local TargetPos
    if Container:FindFirstChild(State.TargetUid) then
        TargetPos = GetPosition(Container:FindFirstChild(State.TargetUid))
    elseif workspace:FindFirstChild(State.TargetUid) then
        TargetPos = GetPosition(workspace:FindFirstChild(State.TargetUid))
    end
    if not TargetPos then AutoStop() return end

    local WaitTime = GetNearestMapWait(TargetPos)

    WalkTP(TargetPos, false, Config.FlyTPDistance, false, function()
        task.spawn(function()
            task.wait(WaitTime)
            if not State.Running then return end
            
            State.Step = "6_collect_target"
            State.TargetCollected = false
            State.CurrentEggUid = State.TargetUid
            
            local CollectStartTime = tick()
            
            while State.Running and State.Step == "6_collect_target" do
                task.wait(Config.CollectInterval)
                RemoteCollectTarget()
                
                if tick() - CollectStartTime >= Config.CollectTargetTimeout then
                    warn(string.format("[TeleportSystem] ⏱️ Collect Timeout (%ds) → Skip", Config.CollectTargetTimeout))
                    State.Step = "6b_timeout"
                    task.wait(0.3)
                    Step7_ShotToSafePosition()
                    return
                end
            end
        end)
    end)
end

Step7_ShotToSafePosition = function()
    if not State.Running then return end
    State.Step = "7_push_up"
    StopLock()

    PushUp(Config.PushUpOffset, function()
        local SafePos, SafeName = GetSafePosition()
        State.SafeName = SafeName
        State.SafePosition = SafePos

        local ShotTarget = SafePos + Vector3.new(0, Config.PushUpOffset, 0)

        ShotTP(ShotTarget, Config.ShotTPTime2, false, function()
            CFrameInstant(SafePos, function()
                CleanupMovers()
                StartLock(SafePos)

                task.spawn(function()
                    task.wait(Config.LockWait)
                    RemoteDrop()
                    State.DropDone = true
                    State.CurrentEggUid = nil
                    task.wait(0.2)
                    StopLock()
                    
                    Step8c_CheckDistanceAndRecover()
                end)
            end)
        end)
    end)
end

Step8c_CheckDistanceAndRecover = function()
    if not State.Running then return end
    State.Step = "8c_check_distance"

    local TargetPos
    if Container:FindFirstChild(State.TargetUid) then
        TargetPos = GetPosition(Container:FindFirstChild(State.TargetUid))
    elseif workspace:FindFirstChild(State.TargetUid) then
        TargetPos = GetPosition(workspace:FindFirstChild(State.TargetUid))
    end

    if not TargetPos then
        State.IsRecoverMode = true
        Step8b_WalkToCollectAgain()
        return
    end

    local Hum, Root = GetHumanoid()
    if not Root then AutoStop() return end

    local Dist = (Root.Position - TargetPos).Magnitude
    if Dist < Config.RecoverDistanceThreshold then
        State.IsRecoverMode = true
        Step8b_WalkToCollectAgain()
    else
        State.RepeatCount = State.RepeatCount + 1
        if State.RepeatCount >= Config.MaxRepeatCount then AutoStop() return end
        task.wait(0.5)
        Step1_WalkToFirstEgg()
    end
end

Step8b_WalkToCollectAgain = function()
    if not State.Running then return end
    State.Step = "8b_to_collect_again"

    local TargetPos
    if Container:FindFirstChild(State.TargetUid) then
        TargetPos = GetPosition(Container:FindFirstChild(State.TargetUid))
    elseif workspace:FindFirstChild(State.TargetUid) then
        TargetPos = GetPosition(workspace:FindFirstChild(State.TargetUid))
    end
    if not TargetPos then Step9_WalkToSwapPosition() return end

    FlyTPAndLock(TargetPos, Config.FlyOffset, function()
        State.Step = "8b_collect_again"
        State.CollectedAgain = false
        State.CurrentEggUid = State.TargetUid
        
        task.spawn(function()
            local CollectStartTime = tick()
            
            while State.Running and State.Step == "8b_collect_again" do
                task.wait(Config.CollectInterval)
                RemoteCollectTarget()
                
                if tick() - CollectStartTime >= Config.CollectTargetTimeout then
                    warn(string.format("[TeleportSystem] ⏱️ Collect Again Timeout (%ds) → Skip", Config.CollectTargetTimeout))
                    State.Step = "8b_timeout"
                    task.wait(0.3)
                    Step9_WalkToSwapPosition()
                    return
                end
            end
        end)
    end)
end

-- ==================================================
-- ✅ STEP 9 (រក្សាទុកសម្រាប់ Timeout Only)
-- ==================================================
Step9_WalkToSwapPosition = function()
    if not State.Running then return end
    State.Step = "9_to_swap"

    local SafeName = State.SafeName or "P1_Top1"
    local WalkPos = Config.Position1_Top2

    if SafeName == "P1_Top1" then
        WalkPos = Config.Position1_Top2
    elseif SafeName == "P2_Top1" then
        WalkPos = Config.Position2_Top2
    end

    WalkTP(WalkPos, false, false, false, function()
        State.Step = "10_done"
        task.wait(0.2)
        AutoStop()
    end)
end

StartEggGoneCheck = function()
    if State.EggGoneCheckThread then
        pcall(function() task.cancel(State.EggGoneCheckThread) end)
        State.EggGoneCheckThread = nil
    end

    State.EggGoneCheckThread = task.spawn(function()
        while State.Running do
            task.wait(Config.EggGoneCheckInterval)

            if State.CurrentEggUid then
                if IsEggGone(State.CurrentEggUid) then
                    AutoStop()
                    return
                end
            end

            if State.TargetUid and not State.DropDone then
                if IsEggGone(State.TargetUid) then
                    AutoStop()
                    return
                end
            end

            if State.FirstEggUid and not State.FirstDropDone then
                if IsEggGone(State.FirstEggUid) then
                    AutoStop()
                    return
                end
            end
        end
    end)
end

-- ==================================================
-- ✅ SETUP DROP HELD EGG (Step 8b → Wait 1s → Short TP → Top2)
-- ==================================================
SetupDropHeldEgg = function()
    local PG = Player:FindFirstChild("PlayerGui") or Player:WaitForChild("PlayerGui", 5)
    if not PG then return end
    State.DropHeldEgg = PG:FindFirstChild("DropHeldEgg")
    if not State.DropHeldEgg then warn("[TeleportSystem] DropHeldEgg not found!") return end
    if State.DropHeldEggConnection then State.DropHeldEggConnection:Disconnect() State.DropHeldEggConnection = nil end

    State.DropHeldEggConnection = State.DropHeldEgg:GetPropertyChangedSignal("Enabled"):Connect(function()
        local IsEnabled = State.DropHeldEgg.Enabled == true

        -- ✅ Step 2: First Egg Collect
        if IsEnabled and State.Running and State.Step == "2_collect_first" then
            State.FirstCollected = true
            State.CurrentEggUid = State.FirstEggUid
            StopLock()
            State.Step = "2b_drop_first"
            task.spawn(function()
                task.wait(0.05)
                State.FirstDropDone = true
                State.CurrentEggUid = nil
                task.wait(0.2)
                Step3b_AfterDropFirst()
            end)
        end

        -- ✅ Step 6: Target Collect
        if IsEnabled and State.Running and State.Step == "6_collect_target" then
            State.TargetCollected = true
            State.CurrentEggUid = State.TargetUid
            StopLock()
            task.spawn(function()
                task.wait(0.02)
                Step7_ShotToSafePosition()
            end)
        end

        -- ✅ Step 8b: Collect Again → Wait 1s → Short TP → Top2
        if IsEnabled and State.Running and State.Step == "8b_collect_again" then
            State.CollectedAgain = true
            State.CurrentEggUid = State.TargetUid
            StopLock()
            task.spawn(function()
                task.wait(0.2)
                
                -- ✅ Wait 1s
                print(string.format("[TeleportSystem] ⏱️ Wait %ds → Short TP Top2", Config.Top2ShortTPWait))
                task.wait(Config.Top2ShortTPWait)
                
                if not State.Running then return end
                
                -- ✅ Get Top2 Position
                local SafeName = State.SafeName or "P1_Top1"
                local Top2Pos = Config.Position1_Top2
                
                if SafeName == "P1_Top1" then
                    Top2Pos = Config.Position1_Top2
                elseif SafeName == "P2_Top1" then
                    Top2Pos = Config.Position2_Top2
                end
                
                print(string.format("[TeleportSystem] ⚡ Short TP → Top2 | %s", SafeName))
                
                -- ✅ Short TP → Top2
                ShotTPWithStop(Top2Pos, Config.Top2ShotTPTime, Config.Top2StopDistance, function()
                    print("[TeleportSystem] ✅ At Top2")
                    task.wait(0.3)
                    AutoStop()
                end)
            end)
        end
    end)
end

StartProcess = function()
    if State.Running then AutoStop() end
    task.wait(0.2)

    if not State.TargetUid then
        warn("[TeleportSystem] ⚠️ No Target UID → Call Manager")
        NotifyComplete()
        return
    end
    
    if string.find(State.TargetUid, "FirstAreaEgg") then
        warn("[TeleportSystem] ⚠️ Target ជា First Egg!")
        NotifyComplete()
        return
    end
    
    local Players = game:GetService("Players")
    for _, P in ipairs(Players:GetPlayers()) do
        if P.Name == State.TargetUid or P.DisplayName == State.TargetUid then
            warn("[TeleportSystem] ⚠️ Target ជា Player!")
            NotifyComplete()
            return
        end
    end
    
    local TargetInContainer = Container:FindFirstChild(State.TargetUid)
    local TargetInWorkspace = workspace:FindFirstChild(State.TargetUid)
    
    if not TargetInContainer and not TargetInWorkspace then
        warn("[TeleportSystem] ⚠️ Target not found!")
        NotifyComplete()
        return
    end

    local FirstEggUid, FirstEggSlotKey = FindNearestFirstEgg()
    
    if not FirstEggUid or not FirstEggSlotKey then
        warn("[TeleportSystem] ⚠️ First Egg not found → Call Manager")
        NotifyComplete()
        return
    end

    print(string.format("[TeleportSystem] 🥚 First Egg: %s", FirstEggUid))
    print(string.format("[TeleportSystem] 🎯 Target Egg: %s", State.TargetUid))

    SavePlayerStats()

    State.Running = true
    State.Step = "idle"
    State.FirstEggUid = FirstEggUid
    State.FirstEggSlotKey = FirstEggSlotKey
    State.FirstCollected = false
    State.TargetCollected = false
    State.CollectedAgain = false
    State.DropDone = false
    State.CollectAttempts = 0
    State.FirstDropDone = false
    State.RepeatCount = 0
    State.IsRecoverMode = false
    State.SafePosition = nil
    State.SafeName = nil
    State.CurrentEggUid = nil

    SetupDropHeldEgg()
    StartEggGoneCheck()

    task.spawn(function()
        task.wait(0.3)
        Step1_WalkToFirstEgg()
    end)
end

FullReset = function()
    StopLock()
    CleanupMovers()
    RestoreStats()

    if State.DropHeldEggConnection then
        State.DropHeldEggConnection:Disconnect()
        State.DropHeldEggConnection = nil
    end
    State.DropHeldEgg = nil

    if State.EggGoneCheckThread then
        pcall(function() task.cancel(State.EggGoneCheckThread) end)
        State.EggGoneCheckThread = nil
    end

    State.Running = false
    State.Step = "idle"
    State.FirstCollected = false
    State.TargetCollected = false
    State.CollectedAgain = false
    State.DropDone = false
    State.FirstDropDone = false
    State.RepeatCount = 0
    State.IsRecoverMode = false
    State.SafePosition = nil
    State.SafeName = nil
    State.CurrentEggUid = nil
    State.FirstEggUid = nil
    State.FirstEggSlotKey = nil

    print("[TeleportSystem] Full Reset + Reset First Egg")
end

Player.CharacterAdded:Connect(function(Char)
    if not State.Running then return end
    
    print("[TeleportSystem] 🔄 Character Respawned → Resume")
    task.wait(3)
    
    if State.TargetUid then
        FullReset()
        task.wait(0.5)
        StartProcess()
    end
end)

local TeleportSystem = {}

function TeleportSystem.Enable()
    if State.Running then return end
    if not CollectEvent then warn("[TeleportSystem] CollectEvent not found") return end
    if not DropEvent then warn("[TeleportSystem] DropEvent not found") return end
    
    if not State.TargetUid then
        warn("[TeleportSystem] ⚠️ No Target UID → Call Manager")
        NotifyComplete()
        return
    end

    FullReset()
    StartProcess()

    print("[TeleportSystem] ON | Target: " .. tostring(State.TargetUid))
end

function TeleportSystem.Disable()
    FullReset()
    print("[TeleportSystem] OFF")
end

function TeleportSystem.SetTargetId(Id)
    State.TargetUid = Id
    print("[TeleportSystem] 🎯 Target UID Received: " .. tostring(Id))
    State.FirstEggUid = nil
    State.FirstEggSlotKey = nil
end

function TeleportSystem.SetOnComplete(Callback)
    State.OnComplete = Callback
end

function TeleportSystem.GetSavedWalkSpeed() return State.SavedWalkSpeed end
function TeleportSystem.GetWalkSpeed() return GetPlayerSpeed() end
function TeleportSystem.IsEnabled() return State.Running end
function TeleportSystem.GetTargetId() return State.TargetUid end

_G.VOIDCXZ_TeleportSystem = TeleportSystem

print("✅ TeleportSystem Loaded (v36 FINAL — Step 8b: Wait 1s → Short TP Top2)")
]]
